  [1101] = "{id=1101,NameZh='休朗克',ShowName=2,GuildEmblem='icon_1_2',AtlasOpt='career',Position='王国之盾',Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,VisitVocal='Npc/Xiulangke_2',EndVocal='Npc/Xiulangke_1-Npc/Xiulangke_3',AdventureSort=27,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='一个豪迈的络腮胡大叔，健硕的肌肉上有着无数的伤痕和刀疤，仿佛在向冒险者倾诉他曾经的那些辉煌战果…（日语CV：石田彰）',MoveSpdRate=1,DefaultDialog=2266,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,ManualMap=1,DefaultRolePartID=1026,}",
