  [1103] = "{id=1103,NameZh='伊丝米儿',ShowName=2,GuildEmblem='icon_3_2',AtlasOpt='career',Position='暗影之手',Body=22,Eye=2,Gender=2,BodyDefaultColor=0,Hair=13,Head=45013,VisitVocal='Npc/Yisimier_1-Npc/Yisimier_2-Npc/Yisimier_3',AdventureSort=24,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='将自己隐藏在黑暗中的女子，感觉不到一丝气息存在，是个背负着各种不祥传说的人。沉默寡言，等对方感觉到其杀气的时候已经离死亡不远了。（日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=2268,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,ManualMap=1,DefaultRolePartID=1114,}",
  [1104] = "{id=1104,NameZh='卡巴克',ShowName=2,GuildEmblem='icon_4_2',AtlasOpt='career',Position='白银微风',Body=29,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45089,VisitVocal='Npc/Kabake_1-Npc/Kabake_2',AdventureSort=25,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='穿着东方风的贵族气质男子，喜欢在下午优雅地喝着红茶。高高在上的皇家气质和某种说不出的奇怪气场让人觉得和其谈话压力甚大…（日语CV：杉山紀彰）',MoveSpdRate=1,DefaultDialog=2269,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ManualMap=1,DefaultRolePartID=1012,}",
  [1105] = "{id=1105,NameZh='莱伊娜丝',ShowName=2,GuildEmblem='icon_5_2',AtlasOpt='career',Position='圣诗之歌',Body=40,Eye=2,Gender=2,BodyDefaultColor=0,Hair=14,Head=45081,VisitVocal='Npc/Laiyinasi_1-Npc/Laiyinasi_2-Npc/Laiyinasi_3',AdventureSort=26,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='一位令人敬重的修女，从其身上能感受到圣母般的慈爱。对所有人都非常关爱，尤其对想转职为服事系的冒险者，会给予极大的帮助和指导。（日语CV：大谷育江）',MoveSpdRate=1,DefaultDialog=2270,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,ManualMap=1,DefaultRolePartID=1108,}",
  [1106] = "{id=1106,NameZh='固特伊',ShowName=2,GuildEmblem='guild_12',AtlasOpt='guild',Position='创造者',Body=45,Eye=1,Gender=1,BodyDefaultColor=0,Hair=3,Head=45072,VisitVocal='Npc/Guteyi_1-Npc/Guteyi_4-Npc/Guteyi_5',EndVocal='Npc/Guteyi_2-Npc/Guteyi_3-Npc/Guteyi_6',MoveSpdRate=1,DefaultDialog=2271,IsVeer=1,move=0,AccessRange=2,Emoji=19,Action=9,DefaultRolePartID=1066,}",
  [1107] = "{id=1107,NameZh='勋',ShowName=2,Guild='克里图拉学院',GuildEmblem='icon_2_2',AtlasOpt='career',Position='员工',Body=1022,Gender=1,Icon='Rune_Ambassador',AdventureSort=113,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='曾在初心者学院任勤杂工，为人老实，做事认真。每当看到有新冒险者毕业的时候，其脸上总是洋溢出灿烂的笑容。',MoveSpdRate=1,DefaultDialog=4076,IsVeer=1,AccessRange=2,Emoji=20,Action=9,ManualMap=7,DefaultRolePartID=1067,}",
  [1108] = "{id=1108,NameZh='亚瑞',ShowName=2,Guild='普隆德拉城防军',GuildEmblem='career_01_2',AtlasOpt='guild',Position='将军',Body=7,Eye=1,Gender=1,Hair=2,Head=45072,VisitVocal='Npc/Ayrui_1-Npc/Ayrui_2-Npc/Ayrui_3',EndVocal='Npc/Ayrui_4-Npc/Ayrui_5',AdventureSort=115,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='勇敢正义的亚瑞是城防军中最值得信赖的大叔，从小生活在普隆德拉的他誓死保卫他所热血的土地。',MoveSpdRate=1,DefaultDialog=92029,IsVeer=1,AccessRange=2,Emoji=21,Action=9,ManualMap=7,DefaultRolePartID=1052,}",
