  [1183] = "{id=1183,NameZh='雷诺里瑟',ShowName=2,Position='史上最强炼金术士',Body=1089,Gender=1,RightHand=400141,Hair=2,Icon='Raynojose',AdventureSort=29,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='被称为史上最强炼金术师的雷诺一直在研究着一些不为人知的秘密，他的炼金术早已摆脱了物质层面，他已经可以通过一些手段来影响冒险者肌肉神经记忆，当然等价交换也是炼金术师们严格遵守的规则，如果你想体验这种奇妙的感觉，你需要用一颗非常稀有的“轮回之石”去交换。',MoveSpdRate=1,DefaultDialog=96413,IsVeer=1,move=0,AccessRange=2,Emoji=2,Action=9,ManualMap=1,DefaultRolePartID=1053,}",
