  [1552] = "{id=1552,NameZh='哈沃德',ShowName=2,Position='神工匠',Body=47,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,AdventureSort=175,AdventureValue=30,AdventureReward={item={{110,5}}},Condition=5,Desc='答应“给予可以制造传说中的武器的身体”这个邀请而被卷入了一场神秘事件的神工匠。成为有名工匠弟子的他，将人生的全部奉献给武器的制造，传说他的一生是除了制作武器以外完全不感兴趣，彻头彻尾的铁匠。',MoveSpdRate=1,DefaultDialog=96880,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=16,DefaultRolePartID=1005,}",
