  [2157] = "{id=2157,NameZh='猫小友',ShowName=2,MapIcon='map_enchant',Body=1114,Gender=3,BodyDefaultColor=0,RightHand=40603,Hair=0,Icon='KongfuCat',AdventureSort=147,AdventureValue=30,AdventureReward={item={{110,5}}},Condition=5,Desc='受到了“堕落天使匠人”的启发，小友学会了附魔，不知什么原因离开了猫猫岛，来到了这片大陆。',MoveSpdRate=1,DefaultDialog=7032,NpcFunction={{type=307},{name='附魔小店',param=1,type=850}},FnIcon='62',FnDesc='附魔小店',IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,ManualMap=13,DefaultRolePartID=1165,}",
  [2158] = "{id=2158,NameZh='弗雷德',ShowName=2,MapIcon='map_shop',Position='惊奇玩具商',Body=1098,Gender=1,RightHand=400088,Hair=4,Head=400089,Icon='2158',AdventureSort=6,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='古灵精怪的小鬼，父亲是鼎鼎大名的发明家和收藏家皮耶罗，从小就被父亲影响的他也喜欢捣鼓各种神奇的小玩意儿，在首都的孩子群中很有人气。是节日派对的道具达人！',MoveSpdRate=1,DefaultDialog=131483,NpcFunction={{name='惊奇玩具',param=11,type=600},{type=2100}},FnIcon='65',FnDesc='惊奇玩具',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=1,DefaultRolePartID=1041,}",
  [2159] = "{id=2159,NameZh='B格猫星人',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',MapIcon='map_exchange',AtlasOpt='guild',Position='交易所职员',Body=1102,Gender=1,Hair=1102,Face=400144,VisitVocal='Npc/BigcatMan_1-Npc/BigcatMan_2-Npc/BigcatMan_5-Npc/BigcatMan_6',EndVocal='Npc/BigcatMan_3-Npc/BigcatMan_4-Npc/BigcatMan_7',Icon='BigcatMan',AdventureSort=30,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='大陆上最神秘的经贸平台组织，旗下业务范围几乎覆盖整个米德加尔特，甚至连遥远的海外也有其分公司，据爱尔贝塔商业报透露。这帮神秘的黑衣墨镜家伙几乎已经控制了整个大陆的交易和经济…',DefaultDialog=8155,NpcFunction={{type=5000}},FnIcon='icon_60',FnDesc='交易所',IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,LoadShowSize=0.9,ManualMap=1,Purikura='BigCat_Star',PurikuraBG='Adventure_bg_NPC2',DefaultDialog_class1=401258,DefaultRolePartID=1057,}",
