  [2184] = "{id=2184,NameZh='美羽',DisablePlayshow=1,ShowName=2,Position='（休假中）',Body=1103,Gender=2,RightHand=400145,Hair=1103,Head=145112,VisitVocal='Npc/MiuRest_1-Npc/MiuRest_5',EndVocal='Npc/MiuRest_2-Npc/MiuRest_3-Npc/MiuRest_4',Desc='傲娇系的美少女，拥有异色的双瞳，喜欢穿猫系的服装和饰品，一直和他的好友，花猫卡斯提娜在一起。虽然外表是超级美少女，被人问到体重和年龄会炸毛。',DefaultDialog=9584,FnIcon='65',FnDesc='休假中的美少女',IsVeer=0,move=0,AccessRange=5,Emoji=13,Action=9,NoShowIcon=1,Purikura='Meiyu',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1100,}",
