  [2190] = "{id=2190,NameZh='拉芙·黛丝',DisableWait=1,DisablePlayshow=1,ShowName=2,Guild='B格猫星',GuildEmblem='map_Official-NPC',MapIcon='map_Official-NPC',AtlasOpt='guild',Position='恋之神',Body=1145,Gender=3,BodyDefaultColor=0,Desc='她居无定所，但是在每年特殊的日子才会来到普隆德拉，她认为爱情是最美好的事物，她真切地希望有情人能够终成眷属。',MoveSpdRate=1,DefaultDialog=82177,NpcFunction={{type=6004}},IsVeer=1,move=0,Emoji=14,Action=9,NoShowIcon=1,DefaultRolePartID=1162,}",
