  [2196] = "{id=2196,NameZh='乌尔德',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',MapIcon='map_Official-NPC',AtlasOpt='guild',Position='星座占卜',Body=1195,Gender=3,BodyDefaultColor=0,Desc='年轻的恋人啊，爱情之神会将你和命定之人的手牵到一起，共同面对今后的冒险之路。你准备好接受爱神使者的占卜了吗？',MoveSpdRate=1,DefaultDialog=30019,NpcFunction={{type=8005},{name='星座小店',param=1,type=906},{type=8009}},IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,DefaultRolePartID=1165,}",
  [2197] = "{id=2197,NameZh='贝尔丹迪',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',AtlasOpt='guild',Position='星座占卜',Body=1195,Gender=3,BodyDefaultColor=0,Desc='古之往昔，黄金年代终告完结。罪与罚降临世间，世界之树的枝芽也在叹息着时光。女神告诫着世间的人们。如今女神的祝福与期待依然留存于人间。被继承的心灵将为人们带来福音。',MoveSpdRate=1,DefaultDialog=30019,NpcFunction={{type=8006},{name='星座小店',param=1,type=906},{type=8009}},FnIcon='icon_40',FnDesc='星座占卜',IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,DefaultRolePartID=1169,}",
  [2198] = "{id=2198,NameZh='诗蔻迪',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',MapIcon='map_Official-NPC',AtlasOpt='guild',Position='冒险占卜',Body=1197,Gender=3,BodyDefaultColor=0,Desc='诸神陨落，魔王又将卷土重来。战胜黑暗的永远是光明，荣耀属于最勇敢的冒险者！',MoveSpdRate=1,DefaultDialog=30019,NpcFunction={{type=6004}},IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,DefaultRolePartID=1165,}",
