  [2528] = "{id=2528,NameZh='雷吉·琼斯',DisablePlayshow=1,ShowName=2,Position='派遣队队长',Body=5,Eye=1,Gender=1,Hair=5,AdventureSort=184,AdventureValue=35,AdventureReward={item={{110,5}}},Condition=5,Desc='是普隆德拉王国派遣驻守在斐扬的派遣队队长，为人勇敢冷静，是不可多得的人才。',MoveSpdRate=1,DefaultDialog=131492,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=18,DefaultRolePartID=1031,}",
