  [2532] = "{id=2532,NameZh='凯文·雷诺',DisablePlayshow=1,ShowName=2,Position='猎人',Body=29,Eye=1,Gender=1,Hair=4,AdventureSort=190,AdventureValue=30,AdventureReward={item={{110,5}}},Condition=5,Desc='诺雅的狂热追求者，为了追到美丽的诺雅，他甚至花了重金在天水之国报了恋爱补习班。',MoveSpdRate=1,DefaultDialog=131496,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=19,DefaultRolePartID=1049,}",
