  [2534] = "{id=2534,NameZh='夏尔顿',DisablePlayshow=1,ShowName=2,Position='城外小村村民',Body=29,Eye=1,Gender=1,RightHand=41206,Hair=6,HeadDefaultColor=2,AdventureSort=188,AdventureValue=35,AdventureReward={item={{110,5}}},Condition=5,Desc='受到黑衣人诱惑帮助黑衣人寻找幽光药剂和伊米尔之心的小村村民，渴望拥有强大的力量，却没有那样的天赋。',MoveSpdRate=1,DefaultDialog=131498,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=19,DefaultRolePartID=1010,}",
  [2535] = "{id=2535,NameZh='医者诺雅',DisablePlayshow=1,ShowName=2,Position='城外小村村民',Body=1101,Gender=2,Hair=14,Icon='2535',AdventureSort=189,AdventureValue=35,AdventureReward={item={{110,5}}},Condition=5,Desc='斐扬南部小村里唯一的医生，也是一名强大的药剂师。是凯文·雷诺的梦中情人。',MoveSpdRate=1,DefaultDialog=131499,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=19,DefaultRolePartID=1105,}",
