  [2540] = "{id=2540,NameZh='索罗·图克',DisablePlayshow=1,ShowName=2,Position='斐扬村民',Body=31,Eye=1,Gender=1,Hair=10,AdventureSort=183,AdventureValue=35,AdventureReward={item={{110,5}}},Condition=5,Desc='来自遥远的梦罗克，是冒险者公会的元老之一，也是外号“狂怒”的顶尖游侠，现在隐于斐扬，对女儿诺雅非常宠溺。',MoveSpdRate=1,DefaultDialog=131504,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=18,DefaultRolePartID=1002,}",
  [2541] = "{id=2541,NameZh='星痕',DisablePlayshow=1,ShowName=2,Position='斐扬占卜师',Body=14,Eye=2,Gender=2,RightHand=40603,Hair=14,Head=45067,VisitVocal='Npc/XingHen_1-Npc/XingHen_4-Npc/XingHen_5',EndVocal='Npc/XingHen_2-Npc/XingHen_3',AdventureSort=185,AdventureValue=35,AdventureReward={item={{110,5}}},Condition=5,Desc='身为占卜师的她一直是斐扬的指引者，自从世代相传的水晶球碎裂后，就隐居于斐扬，专心教导下一任占卜师。',MoveSpdRate=1,DefaultDialog=131505,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=18,DefaultRolePartID=1126,}",
