  [3024] = "{id=3024,NameZh='邓肯·星耀',ShowName=2,Guild='皇家骑士团',GuildEmblem='career_01_2',AtlasOpt='guild',Position='先遣队队员',Body=5,Eye=1,Gender=1,Hair=5,Head=45097,AdventureSort=213,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='星耀三兄弟的大哥，极具冒险精神，但又非常谨慎的一个人。最讨厌的东西是胡萝卜。',MoveSpdRate=1,DefaultDialog=1312431,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=23,DefaultRolePartID=1049,}",
  [3025] = "{id=3025,NameZh='麦肯锡·星耀',ShowName=2,Guild='皇家骑士团',GuildEmblem='career_01_2',AtlasOpt='guild',Position='先遣队队员',Body=5,Eye=1,Gender=1,Hair=6,Head=45097,AdventureSort=214,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='星耀三兄弟的老二，平时性格有些散漫，但是执行任务时非常谨慎，是不可多得的人才。',MoveSpdRate=1,DefaultDialog=1312432,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=23,DefaultRolePartID=1032,}",
  [3026] = "{id=3026,NameZh='巴鲁克·星耀',ShowName=2,Guild='皇家骑士团',GuildEmblem='career_01_2',AtlasOpt='guild',Position='先遣队队员',Body=5,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45097,AdventureSort=215,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='星耀三兄弟中最小的，他最大的愿望就是调回普隆德拉，然后娶一个城里的姑娘。',MoveSpdRate=1,DefaultDialog=1312433,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,ManualMap=23,DefaultRolePartID=1033,}",
  [3027] = "{id=3027,NameZh='布朗·克伯格',ShowName=2,Guild='皇家骑士团',GuildEmblem='career_01_2',AtlasOpt='guild',Position='先遣队队长',Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,HeadDefaultColor=6,Head=45097,AdventureSort=216,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='兽人村的先遣队队长，为人严肃，任务完成的一丝不苟，不过却拿巴鲁克毫无办法。',MoveSpdRate=1,DefaultDialog=1312434,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,ManualMap=23,DefaultRolePartID=1010,}",
