  [4266] = "{id=4266,NameZh='福金',ShowName=2,Body=1162,Gender=1,BodyDefaultColor=0,Hair=4,HeadDefaultColor=4,Icon='FullKing',AdventureSort=235,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='专注于研究历史，考证古迹的学者。得到卢恩王国皇家许可，目前在米德加尔特各地考古。带着不少学徒，都是无家可归的流浪儿，他供学徒们衣食住宿，而学徒们则作为他的助手协助考古，逐渐这个考古队形成了一定规模，在米德加尔特极富盛名。',MoveSpdRate=1,DefaultDialog=81697,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=27,DefaultRolePartID=1012,}",
