  [4272] = "{id=4272,NameZh='大运',DisablePlayshow=1,ShowName=2,Guild='克雷斯特同盟军',GuildEmblem='guild_14',AtlasOpt='guild',Body=60,Eye=1,Gender=1,Hair=8,HeadDefaultColor=6,Icon='NPC_Dayun',Desc='放弃了圣光之力，转而修习格斗的大运，希望凭借自己的力量来捍卫整个斐扬，据说斐扬里爱慕大运的人很多。',MoveSpdRate=1,DefaultDialog=1312407,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1015,}",
