  [4277] = "{id=4277,NameZh='艾丽维娅 ',ShowName=2,MapIcon='map_kapula',Position='卡普拉临时雇员',Body=20021,Gender=2,BodyDefaultColor=0,Icon='Alice',AdventureSort=233,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='同盟军进驻古城后，卡普拉公司也决定在古城开设服务点，然而没有在职的卡普拉服务员愿意调到古城工作。于是经过海选招募，向往着进入卡普拉公司工作的热情女孩艾丽维娅终于有幸受雇，成为了古城常驻的卡普拉服务员。虽然是临时雇员，且工作环境恶劣，不过她依然热爱着这份工作。',MoveSpdRate=1,DefaultDialog=81733,NpcFunction={{type=8204},{type=8206},{type=8201},{type=8205},{type=3001}},FnIcon='66',FnDesc='仓库/存储/传送',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=27,DefaultRolePartID=1085,}",
