  [4282] = "{id=4282,NameZh='布雷尔',ShowName=2,Guild='终极决斗俱乐部',GuildEmblem='icon_1_2',Body=27,Eye=1,Gender=1,BodyDefaultColor=0,RightHand=41206,Hair=6,HeadDefaultColor=2,AdventureSort=138,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='从五岁开始每天都要练习三个小时的弓术，现年十八岁的他在弓术的精准度方面可以说是无人可挡的宗师……呃，仅限射靶的精准度，实战不算啦……',MoveSpdRate=1,DefaultDialog=81853,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=12,DefaultRolePartID=1019,}",
  [4283] = "{id=4283,NameZh='安格斯',ShowName=2,Guild='终极决斗俱乐部',GuildEmblem='icon_1_2',Body=35,Eye=1,Gender=1,BodyDefaultColor=0,Hair=7,HeadDefaultColor=3,AdventureSort=139,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='在决斗俱乐部有许多成员靠优秀的身体素质获胜，但安格斯不同，他的身体天赋不如别人，于是他苦心钻研了多年的实战策略，要和他对决，千万要小心他那充满诡计的头脑。',MoveSpdRate=1,DefaultDialog=81854,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=12,DefaultRolePartID=1008,}",
