  [4426] = "{id=4426,NameZh='影子驱魔人',ShowName=2,Body=10130,Gender=3,BodyDefaultColor=0,Icon='Dark_Priest',AdventureSort=238,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='出现在古城下水道的谜之人物，自称“影子驱魔人”，曾经是古城某位先王身边的亲信，因失去了“光明”，沦为隐姓埋名的影子，在不同时期出现过，似乎已活了数百年之久。',MoveSpdRate=1,DefaultDialog=83645,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=28,DefaultRolePartID=1162,}",
  [4427] = "{id=4427,NameZh='猎鹰驱魔人',ShowName=2,Body=10130,Gender=3,BodyDefaultColor=0,Icon='Dark_Priest',AdventureSort=239,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='曾经是古城某位先王身边的亲信，因刚强正直的个性，被恶魔利用。为了挽回朋友的性命与名誉，他答应了恶魔的条件，被恶魔吞噬。',MoveSpdRate=1,DefaultDialog=83654,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=28,DefaultRolePartID=1162,}",
  [4428] = "{id=4428,NameZh='月狼驱魔人',ShowName=2,Body=10130,Gender=3,BodyDefaultColor=0,Icon='Dark_Priest',AdventureSort=240,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='曾经是古城某位先王身边的亲信，因太容易被感情左右，铸成大错，下场非常悲惨，在牢狱中怀着懊悔与悲愤死去。',MoveSpdRate=1,DefaultDialog=83655,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=28,DefaultRolePartID=1164,}",
  [4429] = "{id=4429,NameZh='乌鸦驱魔人',ShowName=2,Body=10130,Gender=3,BodyDefaultColor=0,Icon='Dark_Priest',AdventureSort=241,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='曾经是古城某位先王身边的亲信，无知的仁善使他屡遭朋友利用，并亲手造就了邪恶的诞生。当悔悟之时，为时已晚。',MoveSpdRate=1,DefaultDialog=83656,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=28,DefaultRolePartID=1164,}",
  [4430] = "{id=4430,NameZh='毒蝎驱魔人',ShowName=2,Body=10130,Gender=3,BodyDefaultColor=0,Icon='Dark_Priest',AdventureSort=242,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='曾经是古城某位先王身边的亲信，生前名为“古列弗”，睿智精明，足智多谋。然而智慧是一把双刃剑，它成为了古列弗最信赖的朋友，同时也是将他送上断头台的凶器。',MoveSpdRate=1,DefaultDialog=83657,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=28,DefaultRolePartID=1162,}",
