  [4556] = "{id=4556,NameZh='山葵',ShowName=2,Position='狂风怒涛',Body=1141,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat4',AdventureSort=34,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='以佣兵团的盾牌自称，神秘的猫猫佣兵团成员！山葵是以坚固的防御闻名于世的佣兵，在关键时刻敢于为雇主抵挡致命一击，深得雇主们的信任，有山葵在，雇主们从来不担心自己的生命是否收到威胁！',MoveSpdRate=1,DefaultDialog=84482,NpcFunction={{param={3,1205},type=8100}},IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,Scale=1.2,ManualMap=1,DefaultRolePartID=1166,}",
  [4557] = "{id=4557,NameZh='皇家骑士团士兵',DisablePlayshow=0,ShowName=0,Guild='克雷斯特同盟军',GuildEmblem='guild_14',AtlasOpt='career',Body=5,Eye=1,Gender=1,BodyDefaultColor=0,RightHand=400061,Hair=5,HeadDefaultColor=8,Head=45097,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,DefaultRolePartID=1012,}",
  [4558] = "{id=4558,NameZh='美莎',ShowName=2,Position='优雅之樱',Body=1140,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat3',AdventureSort=35,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='优雅的舞步，高傲神秘的猫猫佣兵团成员！美莎是以魔法攻击著称的佣兵猫，一切在危险在美莎的魔法下都不堪一击，敌人们沉迷于美莎的舞姿，倒在了美莎的魔法之下。雇主们很乐意雇佣美莎这个多才多艺的佣兵猫。',MoveSpdRate=1,DefaultDialog=84632,NpcFunction={{param={4,1206},type=8100}},IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,Scale=1.2,ManualMap=1,DefaultRolePartID=1163,}",
