  [4906] = "{id=4906,NameZh='伊斯塔娜',ShowName=2,Body=26,Eye=2,Gender=2,BodyDefaultColor=0,LeftHand=40728,RightHand=40728,Hair=1013,HeadDefaultColor=8,Wing=47011,Icon='4906',AdventureSort=391,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='作为死者之都的亡魂事务官，伊斯塔娜负责处理生者与死者之间的事务，虽然她每天都在抱怨，但是大家都知道她是个热心的家伙，有传闻说，很久之前伊斯塔娜曾是一位女武神。“每天都在处理这些死人的事真是麻烦死了！”——伊斯塔娜',MoveSpdRate=1,DefaultDialog=107723,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=70,DefaultRolePartID=1089,}",
