  [5114] = "{id=5114,NameZh='花子',ShowName=2,Body=1306,Gender=2,BodyDefaultColor=0,Hair=11,HeadDefaultColor=8,Icon='Nanami2',AdventureSort=371,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='常年待在天水之国最大的一棵樱花树下，花子见证了每对情侣互相许诺的瞬间。想要结婚的冒险者，都需要将自己对爱人的心意告诉花子，请花子向樱花里居住的神明许愿，得到一个吉祥的日期，顺利完成自己的婚事。尽管是万千情侣的红娘，花子自己却是单身，她说她把自己的一生都给了那棵樱花之树……',MoveSpdRate=1,DefaultDialog=56181,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=62,DefaultRolePartID=1123,}",
  [5115] = "{id=5115,NameZh='护泉的狸猫',ShowName=2,Body=10123,Gender=3,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=56194,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1169,}",
  [5116] = "{id=5116,NameZh='相守之灵',ShowName=2,Body=1341,Gender=2,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=56212,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1093,}",
  [5117] = "{id=5117,NameZh='优子',ShowName=2,Position='樱花之间管理人',Body=1307,Gender=2,BodyDefaultColor=0,Hair=36,HeadDefaultColor=9,MoveSpdRate=1,DefaultDialog=56222,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Scale=1.1,DefaultRolePartID=1158,}",
  [5118] = "{id=5118,NameZh='菓子婆婆',ShowName=2,Body=1308,Gender=2,BodyDefaultColor=0,Icon='Wagashi2',AdventureSort=372,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='天水之国最擅长制作果子的老婆婆，每位国民都是吃着她亲手制作的果子长大的。因为年纪大了，现在每天制作果子的精力不够了，只能限量供应果子。如果想要买到婆婆的果子，一定要早点排队哦！',MoveSpdRate=1,DefaultDialog=56403,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=62,DefaultRolePartID=1108,}",
  [5119] = "{id=5119,NameZh='相思地藏',ShowName=2,Body=1318,Gender=1,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=56404,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1062,}",
