  [5121] = "{id=5121,NameZh='樱花地藏',ShowName=2,Body=1318,Gender=1,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=56406,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1007,}",
  [5122] = "{id=5122,NameZh='爱之樱花树',ShowName=2,Body=1345,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ShadowCastOff=1,DefaultRolePartID=1170,}",
  [5123] = "{id=5123,NameZh='面包大叔',ShowName=2,Body=1309,Gender=1,BodyDefaultColor=0,Icon='UncleBakery2',AdventureSort=373,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='如果说菓子婆婆是天水之国的传统，那么面包大叔就是天水之国的摩登。面包大叔原本只是一个普通的面包师傅，按照老师的教育方式按部就班的烤制面包。直到有一天他遇见了自己心爱的女人，为了讨爱人的欢心，他换着花样制作新鲜的烤面包让挑剔的爱人品尝，没想到他的爱人依然离他而去。可是他烤制的特色面包却在天水之国流传开来，大家都喜欢上这些新潮的面包，也算是因祸得福吧。',MoveSpdRate=1,DefaultDialog=56550,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=62,DefaultRolePartID=1011,}",
