  [5200] = "{id=5200,NameZh='驯鹿',ShowName=2,Position='圣诞老人的助手',Body=1776,Gender=3,BodyDefaultColor=0,Mount=25004,Icon='Mount_Alpaca',AdventureSort=351,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='一只脾气不好的羊驼，经常因为自己雪白的皮毛和可爱的小耳朵误认为很无害，实际上一言不合就动手，没事还会欺负一下雪橇。实力强大，战力不俗，是圣诞老人的得力助手之一。',MoveSpdRate=1,DefaultDialog=52053,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=48,IsMountNpc=1,DefaultRolePartID=1168,}",
  [5201] = "{id=5201,NameZh='雪橇',ShowName=2,Position='圣诞老人的助手',Body=57,Eye=1,Gender=1,BodyDefaultColor=0,Hair=1,HeadDefaultColor=4,AdventureSort=352,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='虽然叫做雪橇，却是一个人类，是一名优秀的皇家卫士，看上去十分武威让人很难接近，实际上是姜饼城第一话痨，最关心小朋友和花花草草的安全。因为话多经常被驯鹿嫌弃和欺负，却甘之如饴，是圣诞老人的得力助手之一。',MoveSpdRate=1,DefaultDialog=52054,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=48,DefaultRolePartID=1001,}",
