  [5300] = "{id=5300,NameZh='卡莱娜',ShowName=2,Position='姜饼城守卫官',Body=18,Eye=2,Gender=2,BodyDefaultColor=0,Hair=17,HeadDefaultColor=6,Head=45199,AdventureSort=354,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='糊糊涂涂有些冒失的年轻女孩，虽然有些粗心，但对元素的感知能力非常强，年纪轻轻就成为了一名大法师，是圣诞老人的得力助手之一。',MoveSpdRate=1,DefaultDialog=52197,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=48,DefaultRolePartID=1149,}",
  [5301] = "{id=5301,NameZh='凯拉',ShowName=2,Position='姜饼城守卫官',Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=4,HeadDefaultColor=3,Head=45199,AdventureSort=355,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='一位温柔正直的优秀男人，他的梦想是守护姜饼城所有的人，所以选择了骑士领主作为他的职业。为了帮助姜饼城的居民在雪原生存，他也努力的专研了一些草药学的知识，是圣诞老人的得力助手之一。',MoveSpdRate=1,DefaultDialog=52198,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=48,DefaultRolePartID=1011,}",
