  [5989] = "{id=5989,NameZh='普宁',ShowName=2,Position='朱诺学者',Body=1357,Gender=1,BodyDefaultColor=0,Hair=23,HeadDefaultColor=6,Head=45116,Icon='5989',AdventureSort=378,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='作为朱诺为数不多的学者之一，他一直在协助朱诺政府去维护并改善各种自然灾难问题，为朱诺的建设带来巨大贡献。',MoveSpdRate=1,DefaultDialog=59752,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=63,DefaultRolePartID=1060,}",
  [5990] = "{id=5990,NameZh='嘉尔',ShowName=2,MapIcon='map_kapula',Position='准它公司职员',Body=1373,Gender=1,BodyDefaultColor=0,Head=45103,Icon='5992',AdventureSort=382,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='在朱诺新成立的提供传送服务的公司，嘉尔作为该公司的员工，负责准它传送服务的管理。对他而言，即使是卡普拉这样的巨头，只要敢做，没有不能超越的。',MoveSpdRate=1,DefaultDialog=101069,NpcFunction={{type=8204},{type=8206},{type=8201},{type=8205},{type=3001}},FnIcon='66',FnDesc='仓库/存储/传送',IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=63,DefaultRolePartID=1065,}",
  [5991] = "{id=5991,NameZh='告示牌',DisablePlayshow=1,ShowName=2,Body=1064,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=59753,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ShadowCastOff=1,DefaultRolePartID=1170,}",
  [5992] = "{id=5992,NameZh='里维斯',ShowName=2,Position='准它投票宣传人员',Body=1373,Gender=1,BodyDefaultColor=0,Head=45038,Icon='5992',AdventureSort=383,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='“难道你们不想体验新的传送服务吗？”这是里维斯现在每天念叨最多的一句话。',MoveSpdRate=1,DefaultDialog=59754,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=63,DefaultRolePartID=1062,}",
  [5993] = "{id=5993,NameZh='狄娜',ShowName=2,Position='卡普拉投票宣传人员',Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=16,HeadDefaultColor=9,Head=45078,Icon='5993',AdventureSort=384,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='“传送服务已经被卡普拉垄断，任何企业也别想插足，我们不需要过多的宣传，大家千万别被蒙蔽了双眼。”狄娜貌似对自己的公司服务信心满满，作为老牌传送服务公司，卡普拉的员工也是忠心耿耿。',MoveSpdRate=1,DefaultDialog=59755,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=63,DefaultRolePartID=1143,}",
