  [6461] = "{id=6461,NameZh='默斯曼·岁月',ShowName=2,Position='时钟守护者领袖',Body=15,Eye=1,Gender=1,Hair=4,HeadDefaultColor=2,Head=45035,AdventureSort=301,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='时钟守护者创始人——摩加达·岁月的后代，现任时钟守护者领袖。执行并继承了大贤者巴特蒙德与摩加达·岁月的命令以及遗志，以守护【黄金时钟】为己任的新一代守护者。为人正直勇敢，能够使用摩加达·岁月传下的古代魔法。',MoveSpdRate=1,DefaultDialog=87981,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=43,DefaultRolePartID=1009,}",
  [6462] = "{id=6462,NameZh='赛茜莉雅',ShowName=2,Position='时之魔法师',Body=16,Eye=2,Gender=2,Hair=14,HeadDefaultColor=3,Head=45022,AdventureSort=302,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='时之魔法师——赛茜莉雅，以时间为信仰的流浪魔法师，途经艾尔帕兰时接受默斯曼·岁月的邀请，加入时钟守护者教团。',MoveSpdRate=1,DefaultDialog=87982,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=43,DefaultRolePartID=1138,}",
