  [6493] = "{id=6493,NameZh='威克斯',ShowName=2,Position='炼金术士公会会长',Body=67,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,HeadDefaultColor=6,AdventureSort=303,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='炼金术士公会会长——威克斯，被誉为近百年来最出色的炼金术士，他发明的奇点球用于给危险炼金时创造自由的空间，但过度使用也有着扭曲时空，打开虫洞的力量。',MoveSpdRate=1,DefaultDialog=88093,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=43,DefaultRolePartID=1035,}",
  [6494] = "{id=6494,NameZh='耶格努',ShowName=2,Position='炼金术士公会副会长',Body=67,Eye=1,Gender=1,BodyDefaultColor=0,Hair=21,HeadDefaultColor=4,AdventureSort=304,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='炼金术士公会副会长——耶格努，仅次于威克斯的炼金术士，由于忙于公会事务，近年来疏忽了炼金术的研究，使得他的进步微乎其微。',MoveSpdRate=1,DefaultDialog=88094,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=43,DefaultRolePartID=1045,}",
