  [6645] = "{id=6645,NameZh='耶梦加得',DisablePlayshow=1,ShowName=2,Body=1237,Gender=1,BodyDefaultColor=0,VisitVocal='NPC/MagicSnake_Human_01-NPC/MagicSnake_Human_02',Icon='MagicSnake_Human',AdventureSort=316,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='“尘世巨蟒”耶梦加得，是“魔狼”芬里尔的弟弟，“死亡女神”海拉的哥哥，神族与巨人族混血，拥有着强大而不同于神族的力量由于这份力量，三兄妹遭受了诸神的忌惮，耶梦加得被投入了无尽的深海牢笼，日夜承受着海水巨大的压力。然而他的心中只有一个目标，挣脱牢笼，去拯救被关押在月亮上的哥哥。',MoveSpdRate=1,DefaultDialog=50002,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Scale=1.6,LoadShowSize=0.75,ManualMap=43,Purikura='Jormungand_R',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1058,}",
  [6646] = "{id=6646,NameZh='威克斯',ShowName=2,Position='炼金术士公会会长',Body=67,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,HeadDefaultColor=6,Desc='炼金术士公会会长——威克斯，被誉为近百年来最出色的炼金术士，他发明的奇点球用于给危险炼金时创造自由的空间，但过度使用也有着扭曲时空，打开虫洞的力量。',MoveSpdRate=1,DefaultDialog=50003,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1035,}",
