  [6838] = "{id=6838,NameZh='默斯曼·岁月',DisableWait=1,DisablePlayshow=1,ShowName=2,Position='时钟守护者领袖',Body=15,Eye=1,Gender=1,BodyDefaultColor=0,Hair=4,HeadDefaultColor=2,Head=45035,Desc='时钟守护者创始人——摩加达·岁月的后代，现任时钟守护者领袖。执行并继承了大贤者巴特蒙德与摩加达·岁月的命令以及遗志，以守护【黄金时钟】为己任的新一代守护者。为人正直勇敢，能够使用摩加达·岁月传下的古代魔法。',MoveSpdRate=1,DefaultDialog=87981,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1009,}",
