  [6951] = "{id=6951,NameZh='弗雷德',ShowName=2,MapIcon='map_shop',Position='惊奇玩具商',Body=1098,Gender=1,RightHand=400088,Hair=4,Head=400089,Icon='GreenGleeman_2',AdventureSort=6,AdventureValue=25,AdventureReward={item={{110,5}}},Condition=5,Desc='古灵精怪的小鬼，父亲是鼎鼎大名的发明家和收藏家皮耶罗，从小就被父亲影响的他也喜欢捣鼓各种神奇的小玩意儿，在首都的孩子群中很有人气。是节日派对的道具达人！',MoveSpdRate=1,DefaultDialog=51774,NpcFunction={{name='惊奇玩具',param=11,type=600},{type=2100}},FnIcon='65',FnDesc='惊奇玩具',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1041,}",
