  [6957] = "{id=6957,NameZh='罗恩',ShowName=2,Position='珍妮父亲',Body=1021,Gender=1,Icon='Juno_Ambassador',AdventureSort=353,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='普隆德拉的糖果商人，经营着一家有上百年历史的糖果店，祖传配方的巧克力”圣诞节快乐“被全大陆的孩子们评选为最喜爱的糖果。每年圣诞节期间都会带自己的家人来姜饼城度假，同时为姜饼城的孩子们熬制美味的糖果。',MoveSpdRate=1,DefaultDialog=51746,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1045,}",
  [6958] = "{id=6958,NameZh='帕茜尔',ShowName=2,Position='珍妮母亲',Body=1002,Gender=2,Hair=33,HeadDefaultColor=6,Icon='NPC_woman',MoveSpdRate=1,DefaultDialog=51747,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,DefaultRolePartID=1106,}",
  [6959] = "{id=6959,NameZh='唐尼',ShowName=2,Position='内特爷爷',Body=1108,Gender=1,Icon='Teacher',AdventureSort=362,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='儿子和儿媳妇是大陆著名的冒险者，经常四处游历处理各地魔物泛滥的问题，所以独自一人养育自己的孙子内特，对内特倾注了自己全部的爱，希望把内特培养成儿子一样优秀的冒险者。',MoveSpdRate=1,DefaultDialog=51748,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1036,}",
  [6960] = "{id=6960,NameZh='潘莉',ShowName=2,Position='丽莎姐姐',Body=1273,Gender=2,Icon='6960',AdventureSort=360,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='姜饼城的可怜小女孩，从小就有口吃的毛病，也因为这个原因被其他孩子排斥和笑话。还好有个顽皮可爱的妹妹丽莎逗她开心，最爱自己的爸爸和妹妹，希望永远可以跟他们在一起。',MoveSpdRate=1,DefaultDialog=51749,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1083,}",
  [6961] = "{id=6961,NameZh='索里曼',ShowName=2,Position='丽莎父亲',Body=1012,Gender=1,Hair=1012,Icon='Father',MoveSpdRate=1,DefaultDialog=51750,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1045,}",
  [6962] = "{id=6962,NameZh='贝贝',ShowName=2,Position='打雪仗男孩',Body=1004,Gender=1,Hair=1,HeadDefaultColor=3,Icon='Boy',MoveSpdRate=1,DefaultDialog=51751,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,DefaultRolePartID=1077,}",
