  [6964] = "{id=6964,NameZh='闪电',ShowName=2,Position='堆雪人男孩',Body=1004,Gender=1,Hair=1004,Icon='Boy',MoveSpdRate=1,DefaultDialog=51756,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1036,}",
