  [6966] = "{id=6966,NameZh='苹果',ShowName=2,Position='堆雪人女孩',Body=1273,Gender=4,Icon='Girl2',MoveSpdRate=1,DefaultDialog=51755,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ShadowCastOff=1,DefaultRolePartID=1173,}",
  [6967] = "{id=6967,NameZh='姜饼城民',ShowName=2,Body=1001,Gender=1,Hair=4,HeadDefaultColor=3,Head=400150,Icon='Man',MoveSpdRate=1,DefaultDialog=51757,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1041,}",
  [6968] = "{id=6968,NameZh='姜饼城民',ShowName=2,Body=1002,Gender=2,Hair=15,HeadDefaultColor=4,Head=45139,Icon='NPC_woman',MoveSpdRate=1,DefaultDialog=51758,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,DefaultRolePartID=1147,}",
  [6969] = "{id=6969,NameZh='坎心吉',ShowName=2,Position='大方的老太太',Body=1265,Gender=2,Icon='Elder_F',AdventureSort=356,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='姜饼城的老奶奶，懂得腌制各种美味的泡菜，经常为了照顾小朋友的口味尝试制作一些”古怪“的泡菜，最近似乎在研究巧克力味道泡菜的制作方法。',MoveSpdRate=1,DefaultDialog=51761,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1135,}",
  [6970] = "{id=6970,NameZh='坎塔塔',ShowName=2,Position='毛茸茸老爷爷',Body=1264,Gender=1,Icon='Elder_M',AdventureSort=357,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='有着毛茸茸毛发的老爷爷，虽然年纪大了，却仍保留了一颗童心，喜欢各种恶作剧。因为从小在姜饼城长大，非常了解这里的历史，了解所有人的过往。',MoveSpdRate=1,DefaultDialog=51762,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,Scale=1.2,ManualMap=48,DefaultRolePartID=1009,}",
  [6971] = "{id=6971,NameZh='普兹',ShowName=2,Position='圣诞先生',Body=1263,Gender=1,Icon='Xmas_M',AdventureSort=358,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='喜欢白雪的圣诞先生，因为总是在下雪的时候在室外观雪，被姜饼城的孩子们称为”不怕冷的普兹“，其实被冻病过好多次，如果想知道圣诞村哪里雪景最美，可以去问问他哦。',MoveSpdRate=1,DefaultDialog=51759,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1006,}",
  [6972] = "{id=6972,NameZh='TK',ShowName=2,Body=1004,Gender=1,Hair=1004,HeadDefaultColor=3,Head=45112,Icon='Boy',AdventureSort=359,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='姜饼城的小灵通，有着可爱猫耳的小个子男孩，只喜欢跟小孩子做交易，最讨厌严肃的成年人，谁都不知道他的小口袋里到底装了多少东西，只知道如果代价合适，什么东西他都可以拿出来。',MoveSpdRate=1,DefaultDialog=51753,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ManualMap=48,DefaultRolePartID=1062,}",
  [6973] = "{id=6973,NameZh='珍妮',ShowName=2,Body=1274,Gender=2,BodyDefaultColor=0,Icon='Woman3',MoveSpdRate=1,DefaultDialog=51398,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1118,}",
