  [6983] = "{id=6983,NameZh='雪人',ShowName=2,Body=1259,Gender=3,Icon='Iceman',AdventureSort=361,AdventureValue=40,AdventureReward={item={{110,5}}},Condition=5,Desc='姜饼城的白雪精灵，很少有人知道它是从哪儿来，只知道很早很早以前它就一直在姜饼城，默默地守护者这块地方，是姜饼城孩子们最喜欢的玩伴，陪伴着一代又一代孩子们成长。',MoveSpdRate=1,DefaultDialog=53444,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=48,DefaultRolePartID=1164,}",
