  [7101] = "{id=7101,NameZh='娜娜美',ShowName=2,Body=1306,Gender=2,BodyDefaultColor=0,Hair=11,HeadDefaultColor=9,Icon='Nanami3',AdventureSort=374,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='天水之国的旅游大使，也是去年樱花庆典的樱花小姐。娜娜美出身于天水之国贵族的家庭，可她并没有因此而变得娇宠，她致力于在帮助天水之国里的穷苦人民，还有身份地位卑微的女性。也因为她善良的心灵，她在樱花庆典中被全票选为樱花小姐，在人们的祝福中成为天水之国杰出女性的代表。',MoveSpdRate=1,DefaultDialog=56170,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=62,DefaultRolePartID=1157,}",
