  [7150] = "{id=7150,NameZh='摩根',ShowName=2,Body=1268,Gender=1,BodyDefaultColor=0,Icon='Speaker',MoveSpdRate=1,DefaultDialog=56175,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,Purikura='Morgan',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1046,}",
  [7151] = "{id=7151,NameZh='伊达秀明',ShowName=2,Body=1314,Gender=1,BodyDefaultColor=0,Hair=5,HeadDefaultColor=9,Icon='SakuraBoy2',AdventureSort=375,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='出生于天水之国的巫师家族，伊达秀明从小就有超越常人的灵能。他能看见鬼魂，甚至掌控鬼魂，这些能力也导致了他从小就被普通人孤立。一次偶然的机会，他遇见了同样无法被常人看见的灵——小樱，两个命运相同的人产生了心心相惜的感情。又在漫长的岁月里，这股微妙的情愫转变为了爱意，他爱上了小樱。而好景不长，上天没有给他们相守的机会，当命运之轮开始旋转时无人能抵挡悲剧的降临。',MoveSpdRate=1,DefaultDialog=56173,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NormalDisplay=1,Scale=1.1,ManualMap=62,Purikura='Hideaki',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1078,}",
  [7152] = "{id=7152,NameZh='纸片式神',ShowName=2,Body=1342,Gender=1,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=53175,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1021,}",
  [7153] = "{id=7153,NameZh='伊达千代子',ShowName=2,Body=1310,Gender=2,BodyDefaultColor=0,Hair=31,HeadDefaultColor=3,Icon='ShrineSorceress2',AdventureSort=376,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='天水之国巫女家族伊达的继承人，也是目前神社的掌管人。外表精灵古怪的千代子实际上有一颗脆弱的心。她身为伊达家族的继承人，巫术的实力却逊于自己的弟弟秀明，广受家族长辈责备。她将自己的痛苦藏在一张没心没肺的脸下，却一直默默关心着天水之国的安危，还有自己的弟弟秀明。',MoveSpdRate=1,DefaultDialog=57272,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.1,ManualMap=62,DefaultRolePartID=1113,}",
