  [8310] = "{id=8310,NameZh='波利',ShowName=0,Type='CatchNpc',Race='Plant',Nature='Water',Body=10001,Gender=3,BodyDefaultColor=0,Icon='boli',Desc='RO中的超人气魔物，以其卡哇伊的造型风靡万千玩家，风头直超同胞波波利甚多。非常喜欢苹果，会跟着给它苹果的人们，也会去捡拾各类掉落的道具。能力最弱，是人见人欺的对象，适合初心者练级。',Level=1,MoveSpdRate=2,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1169,}",
  [8311] = "{id=8311,NameZh='小野猪',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Shape='L',Body=10156,Gender=3,BodyDefaultColor=0,Icon='Savage',Desc='杂食性动物，体躯健壮，四肢粗短，有厚实的鬃毛和尖锐的獠牙。虽然是猪，但肉很结实，体魄绝对强健。如果不幸将其惹恼，那对致命的獠牙可会让敌人吃不了兜着走！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1166,}",
  [8312] = "{id=8312,NameZh='溜溜猴',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Shape='S',Body=10013,Gender=3,BodyDefaultColor=0,Icon='Yoyo',Desc='动作快，也很会捡拾道具。虽然很可爱，但是有点烦人。调皮捣蛋的天性让人又爱又恨，尤其是吃完香蕉随意丢香蕉皮的陋习难改，上次国王出行还滑过一跤……',Level=1,MoveSpdRate=3.2,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1169,}",
  [8313] = "{id=8313,NameZh='沙漠幼狼',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Fire',Body=10080,Gender=3,BodyDefaultColor=0,Icon='DesertWolf',Desc='在沙漠生存下来的狼，有比一般狼更强的攻击力，并会主动攻击敌人。适者生存，大自然就是那么残酷。别看其眼睛小，说不定正在狡黠地在打目标的主意呢…',Level=1,MoveSpdRate=1.4,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.6,DefaultRolePartID=1163,}",
  [8314] = "{id=8314,NameZh='曼陀罗种子',ShowName=0,Type='CatchNpc',Race='Plant',Nature='Earth',Shape='S',Body=10122,Gender=3,BodyDefaultColor=0,Icon='Mandala',Desc='迷之植物，个子不大，天性羞涩，擅长捉迷藏。据说只有在迷藏森林服用一种特殊的药水来提升第六感后才能够发现它们。作为种子，萌萌的，遭人怜爱…',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1165,}",
  [8315] = "{id=8315,NameZh='鬼女',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Water',Body=20014,Gender=2,BodyDefaultColor=0,Icon='Sohee',Desc='生前是名貌美如花的普通女子，但不知何故最后含恨而死化为鬼魂继续游荡。或许是情愫的羁绊，亦或是反抗的不甘…谁知道呢，每个人都有自己的故事…',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1112,}",
  [8316] = "{id=8316,NameZh='蛇女伊丝',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Shape='L',Body=10060,Gender=3,BodyDefaultColor=0,Icon='Isis',Desc='上半身裸露、下半身为蛇尾的恶魔，为俄赛里斯之妻。平时在金字塔无微不至地照顾俄赛里斯的生活起居。虽然丈夫绷带缠身，但浓浓的爱意丝毫没有减少。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.3,DefaultRolePartID=1162,}",
  [8317] = "{id=8317,NameZh='小恶魔',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Shape='S',Body=10028,Gender=3,BodyDefaultColor=0,Icon='Deviruchi',Desc='恶魔种族里的小捣蛋鬼，喜欢捉弄玩耍猎物。一旦被其盯上就很难脱身。其手上拿的小三叉戟附有黑暗的魔力，一旦被其触碰便会心智异常！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1167,}",
  [8318] = "{id=8318,NameZh='毕帝特地龙',ShowName=0,Type='CatchNpc',Race='Dragon',Nature='Earth',Body=10062,Gender=3,BodyDefaultColor=0,Icon='Petit',Desc='龙族中比较普通的一种，只能在地面生活。早期米德加尔特的传奇冒险家毕帝特离开吉芬探索中无意间发现了龙区，后人就将普通的龙系魔物冠以他的名字…',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.2,DefaultRolePartID=1166,}",
  [8319] = "{id=8319,NameZh='小巴风特',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Shape='S',Body=10064,Gender=3,BodyDefaultColor=0,RightHand=400046,Icon='Baphomet_S',Desc='巴风特的幼崽，对新鲜事物充满好奇。虽然小巧可爱，但其战斗力不俗。如果被惹怒，一定会挥舞手上的死神镰刀将对方消灭殆尽。就算打不过，还有巴风特撑腰！',Level=1,MoveSpdRate=2,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1168,}",
  [8320] = "{id=8320,NameZh='疯兔',ShowName=0,Type='CatchNpc',Race='Brute',Body=10009,Gender=3,BodyDefaultColor=0,Icon='Eclipse',Desc='疯兔们的守卫使者，体型要大一号，深受疯兔家族各成员的爱戴。传闻之前是只乖巧温顺的普通疯兔，在摘取幸运四叶草的时候不小心染上了研制中的蓝色染发剂才发生异变。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1167,}",
  [8321] = "{id=8321,NameZh='月光小怪兽',ShowName=0,Type='CatchNpc',Race='Plant',Nature='Earth',Shape='S',Body=10165,Gender=3,BodyDefaultColor=0,Icon='Mandala_1',Desc='迷之植物，个子不大，天性羞涩，擅长捉迷藏。据说只有在迷藏森林服用一种特殊的药水来提升第六感后才能够发现它们。作为种子，萌萌的，遭人怜爱…',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1162,}",
  [8325] = "{id=8325,NameZh='小魔女',ShowName=0,Type='CatchNpc',Nature='Undead',Body=10152,Gender=2,BodyDefaultColor=0,LeftHand=400175,Head=400176,Icon='BlackWitch',Desc='经由黑魔法加持，由顽皮的黑猫变成的可爱人类小女孩模样的魔物，喜爱恶作剧。不给糖就会捣蛋！给了也还是要捣蛋！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.8,DefaultRolePartID=1084,}",
  [8326] = "{id=8326,NameZh='玩具士兵',ShowName=0,Type='CatchNpc',Body=10168,Gender=3,BodyDefaultColor=0,Icon='Cruiser',Desc='由精巧到令人赞叹的齿轮机关和复杂结构制作的自律型士兵，经过专家确认真的不是魔导力量驱动！配装武器虽然是玩具，但是有冒险者的受伤报道说被打中依然超疼...',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.8,DefaultRolePartID=1162,}",
  [8327] = "{id=8327,NameZh='玩具熊',ShowName=0,Type='CatchNpc',Race='Formless',Body=10172,Gender=3,BodyDefaultColor=0,Icon='Teddy_Bear',Desc='传说古代某个贵族的千金大小姐挚爱的小玩具熊，在被抛弃后，经年累月而被赋予了灵性，想要知道自己前世的主人而徘徊着，迷茫着。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.3,DefaultRolePartID=1168,}",
  [8329] = "{id=8329,NameZh='魔菇',ShowName=0,Type='CatchNpc',Race='Plant',Nature='Water',Body=10245,Gender=3,BodyDefaultColor=0,Icon='Spore',Desc='    生长在普隆德拉下水道的蘑菇型魔物，虽然看起来像蘑菇但其本质更接近动物，驯服后会发现，它其实是个黏人的爱哭鬼。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1164,}",
  [8330] = "{id=8330,NameZh='蝗虫',ShowName=0,Type='CatchNpc',Race='Insect',Nature='Earth',Body=10246,Gender=3,BodyDefaultColor=0,Icon='Rocker',Desc='极具音乐天赋的蝗虫，自诩为艺术家，如果把它当作宠物的话，想必你的身边一定会热闹（吵闹）非凡。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1168,}",
  [8331] = "{id=8331,NameZh='毒魔菇',ShowName=0,Type='CatchNpc',Race='Plant',Nature='Poison',Body=10247,Gender=3,BodyDefaultColor=0,Icon='PoisonSpore',Desc='魔菇的近亲，因为爱吃鲜嫩毒草而拥有了毒性，没有做好防护措施的话，千万不要贸然招惹它们！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1162,}",
  [8332] = "{id=8332,NameZh='白幽灵',ShowName=0,Type='CatchNpc',Race='Demon',Body=10240,Gender=3,BodyDefaultColor=0,Icon='Whisper',Desc='飘荡在沉船的幽灵魔物，最喜欢做的事就是突然冒出来吓人一大跳！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.4,DefaultRolePartID=1161,}",
  [8333] = "{id=8333,NameZh='大嘴鸟',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Fire',Body=10248,Gender=3,BodyDefaultColor=0,Icon='Pecopeco',Desc='喜欢奔跑的大嘴鸟是沙漠里一道靓丽的风景，想要一只可爱单纯的大嘴鸟做宠物的话，一定要赶上它的速度哦！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.4,DefaultRolePartID=1166,}",
  [8334] = "{id=8334,NameZh='僵尸',ShowName=0,Type='CatchNpc',Race='Undead',Nature='Undead',Body=10239,Gender=3,BodyDefaultColor=0,Head=45043,Icon='Munak',Desc='被妖术唤醒的僵尸，依稀留着对前世的记忆，喜欢人类的温暖。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1169,}",
  [8335] = "{id=8335,NameZh='巨石怪',ShowName=0,Type='CatchNpc',Race='Formless',Body=10257,Gender=3,BodyDefaultColor=0,Icon='Golen',Desc='梦罗克沙漠中的巨石怪，身体十分坚硬，最喜欢吃魔力石板，小爱好是听摇滚乐。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.7,DefaultRolePartID=1165,}",
  [8336] = "{id=8336,NameZh='榔头哥布灵',ShowName=0,Type='CatchNpc',Nature='Earth',Body=10229,Gender=3,BodyDefaultColor=0,LeftHand=400057,RightHand=400051,Face=400083,Icon='Goblin3',Desc='哥布灵家族中脾气最坏的一个，整天活力十足，喜欢拿着榔头敲敲敲！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.8,DefaultRolePartID=1166,}",
  [8337] = "{id=8337,NameZh='兽人战士',ShowName=0,Type='CatchNpc',Nature='Earth',Body=10242,Gender=3,BodyDefaultColor=0,LeftHand=400048,RightHand=400047,Head=45049,Icon='Orc',Desc='兽人村落的中坚力量，最喜欢自己的肌肉，没人的时候，喜欢照镜子臭美，只会臣服于自己认可的强者。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1163,}",
  [8338] = "{id=8338,NameZh='土人',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Body=10241,Gender=3,BodyDefaultColor=0,Icon='Dokebi',Desc='喜欢亮晶晶与力量的土人，说话断断续续的，虽然看起来呆呆的，实际上非常精明...',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=0.55,DefaultRolePartID=1169,}",
  [8339] = "{id=8339,NameZh='恶魔侍者',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Body=10231,Gender=3,BodyDefaultColor=0,Icon='Incubus',Desc='徘徊在古城的恶魔侍者，自从魔王被打败后就一直在找下一位心仪的主人，帅气的外表在女性中拥有超高的人气...',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1165,}",
  [8340] = "{id=8340,NameZh='恶魔女仆',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Shadow',Body=10232,Gender=2,BodyDefaultColor=0,Icon='Succubus',Desc='徘徊在古城的恶魔女仆，自从魔王被打败后就一直在找下一位心仪的主人，你能胜任么？',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1103,}",
  [8341] = "{id=8341,NameZh='土拨鼠',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10233,Gender=3,BodyDefaultColor=0,Icon='Martin',Desc='土拨鼠是艾因布洛克原野上的小居民，虽然个子小，但它的志气可不小！想让他心服口服的做你的宠物，你就必须展现出自己强大的一面！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1169,}",
  [8342] = "{id=8342,NameZh='万圣魔',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Undead',Body=10198,Gender=3,BodyDefaultColor=0,Icon='Quve',Desc='由一团黑漆漆物质构成的怪异魔物，喜欢糖果，幽灵，南瓜灯等一切搞怪好玩的东西，黑色布条是它的最爱，要是走夜路看到漂浮的黑帽子，一定是万圣魔这个捣蛋鬼！',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1167,}",
  [8343] = "{id=8343,NameZh='无颅武士',ShowName=0,Type='CatchNpc',Race='Formless',Nature='Undead',Body=10200,Gender=3,BodyDefaultColor=0,Icon='Dullahan',Desc='生前是克雷斯特汉姆的战士，在去世之后灵魂化作魔物徘徊在尼夫海姆附近的地区，最喜欢铠甲，盔甲之类的东西，似乎对于自己没有头颅这件事很在意......',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1166,}",
  [8344] = "{id=8344,NameZh='熊猫波利',ShowName=0,Type='CatchNpc',Race='Plant',Body=10485,Gender=3,BodyDefaultColor=0,Icon='Panda_poring_1',Desc='拥有罕见配色的波利，对自己的颜色很是自豪，言行中总带着一点点骄傲。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1168,}",
  [8345] = "{id=8345,NameZh='灯笼鱼人',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Water',Shape='S',Body=10480,Gender=3,BodyDefaultColor=0,Icon='Fishmonster_1',Desc='成天打着灯笼，迷迷糊糊的鱼人，谁也不知道它究竟在想些什么。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1168,}",
  [8346] = "{id=8346,NameZh='玩偶魔妖',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10595,Gender=3,BodyDefaultColor=0,Icon='Demon_doll',Desc='可爱的玩偶魔妖，喜欢恶作剧，并不是什么坏心的妖怪啦~',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1167,}",
  [8347] = "{id=8347,NameZh='米米怪',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10596,Gender=3,BodyDefaultColor=0,Icon='Mimi',Desc='看上去是个毛茸茸的小怪物，其实有一颗敏感的内心，不要嘲笑它哦。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1164,}",
  [8348] = "{id=8348,NameZh='年糕波利',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Gender=3,BodyDefaultColor=0,Desc='因不明原因产生变异的波利，以口感Q弹著称（真是相当可疑的描述啊……）',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1161,}",
  [8349] = "{id=8349,NameZh='海豹宝宝',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10636,Gender=3,BodyDefaultColor=0,Icon='Fur_seal',Desc='不惧严寒，灵活机动，必要时还能呼唤风雪的海豹宝宝，在此响应主人的召唤。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1168,}",
  [8350] = "{id=8350,NameZh='奈吉鸟',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10639,Gender=3,BodyDefaultColor=0,Icon='Raggler',Desc='奈吉鸟身材肥胖，走路甚至需要拐杖。但不要小看它，它可是一流的狙击手。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1163,}",
  [8351] = "{id=8351,NameZh='精灵狐',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10684,Gender=3,BodyDefaultColor=0,Icon='n_foxelf',Desc='有着蓬松大耳朵，形似狐狸的魔物。不过和可爱外表不符的，是极强的攻击性和排外性。“人类，滚出我的森林。”如果能开口的话，它们一定会说这样的话吧。',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1161,}",
  [8352] = "{id=8352,NameZh='爆钻伞蜥',ShowName=0,Type='CatchNpc',Race='Brute',Nature='Earth',Body=10688,Gender=3,BodyDefaultColor=0,Icon='n_driller',Desc='每时每刻都张开薄膜的伞蜥。看起来十分滑稽，却有着让菜鸟猎人受苦的攻击力。“爆钻”之名，可不是白叫的哦~',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1,DefaultRolePartID=1168,}",
  [8353] = "{id=8353,NameZh='广寒仙子',ShowName=0,Type='CatchNpc',Race='Demon',Nature='Water',Body=10268,Gender=2,BodyDefaultColor=0,Icon='Sohee_Pet2',Desc='生前是名貌美如花的普通女子，但不知何故最后含恨而死化为鬼魂继续游荡。或许是情愫的羁绊，亦或是反抗的不甘…谁知道呢，每个人都有自己的故事…',Level=1,MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1094,}",
  [8354] = "{id=8354,NameZh='塞壬',ShowName=2,Body=1430,Gender=1,BodyDefaultColor=0,Icon='Seren_new',MoveSpdRate=1,DefaultDialog=107777,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Purikura='Sirens_d',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1038,}",
  [8355] = "{id=8355,NameZh='陌生青年',ShowName=2,Body=1430,Gender=1,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=107778,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1044,}",
  [8356] = "{id=8356,NameZh='华莱士',ShowName=2,Body=1450,Gender=1,BodyDefaultColor=0,Icon='Wallace',AdventureSort=388,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='死者之都酒馆“两个吊死鬼”的老板，一个有故事的大叔（偏爱可爱的小女孩）。酒馆里摆着许多好看的裙子，自称是个人兴趣。关于死者之都的事，十分熟悉。似乎与死亡女神海拉的关系不错。“今天特价酒是乌鸦舌头威士忌，不来上一杯么，小妹妹？”——华莱士',MoveSpdRate=1,DefaultDialog=107779,IsVeer=1,move=0,AccessRange=4,Emoji=0,Action=9,Features=32,ManualMap=70,Purikura='Wallace',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1034,}",
  [8357] = "{id=8357,NameZh='酒瓶',ShowName=2,Type='GatherNPC',Body=1438,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=107780,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,NoShowIcon=1,Features=524320,ShadowCastOff=1,DefaultRolePartID=1172,}",
