  [8431] = "{id=8431,NameZh='血腥草',ShowName=0,Type='GatherNPC',Body=10086,Gender=3,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=301300,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,NoShowIcon=1,Features=524288,DefaultRolePartID=1165,}",
  [8432] = "{id=8432,NameZh='海拉',ShowName=2,Position='死神',Body=1444,Gender=2,BodyDefaultColor=0,Icon='Hela',AdventureSort=385,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='海拉是统治死者之都尼夫海姆的死亡女神，也是魔狼芬里尔与尘世巨蟒耶梦加得的妹妹。虽然外表看起来是个小女孩，但绝对不要小看她的力量。意外的有着孩子气的一面，关于她的一切，对于人们来说依旧是个谜。',MoveSpdRate=1,DefaultDialog=109339,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Features=32,ManualMap=70,Purikura='Hella_1',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1115,}",
  [8433] = "{id=8433,NameZh='格洛特',ShowName=2,Body=10232,Gender=2,BodyDefaultColor=0,Icon='Succubus',AdventureSort=386,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='海拉的女侍从，看守死者之都南部所有的灵魂。对任何事物的反应都很迟钝，对海拉忠心耿耿。脾气不好十分危险，要避免与她正面冲突！',MoveSpdRate=1,DefaultDialog=109340,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=70,DefaultRolePartID=1115,}",
  [8434] = "{id=8434,NameZh='格拉提',ShowName=2,Body=10065,Gender=3,BodyDefaultColor=0,Icon='Incubus',AdventureSort=387,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='海拉的男侍从，看守死者之都北部所有的灵魂。做任何事都十分缓慢，能将一段饭吃上一天。常年被海拉嫌弃，有些自尊心受损，常被格洛特欺负。“你——好——啊——我——叫——格——拉——提。”——格拉提',MoveSpdRate=1,DefaultDialog=109341,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=70,DefaultRolePartID=1169,}",
