  [8939] = "{id=8939,NameZh='海拉',ShowName=2,Body=1444,Gender=2,BodyDefaultColor=0,Icon='Hela',Desc='海拉是统治死者之都尼夫海姆的死亡女神，也是魔狼芬里尔与尘世巨蟒耶梦加得的妹妹。虽然外表看起来是个小女孩，但绝对不要小看她的力量。意外的有着孩子气的一面，关于她的一切，对于人们来说依旧是个谜。',MoveSpdRate=1,DefaultDialog=109339,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Features=32,Purikura='Hella_1',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1115,}",
  [8940] = "{id=8940,NameZh='耶梦加得',ShowName=2,Body=1237,Gender=1,BodyDefaultColor=0,Icon='MagicSnake_Human',MoveSpdRate=1,DefaultDialog=104080,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.6,Purikura='Jormungand_R',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1058,}",
  [8941] = "{id=8941,NameZh='贪婪',ShowName=2,Position='海拉仆从',Body=1486,Eye=1,Gender=1,BodyDefaultColor=0,Hair=25,HeadDefaultColor=4,MoveSpdRate=1,DefaultDialog=10000,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1036,}",
  [8942] = "{id=8942,NameZh='月影幻影',ShowName=2,Position='海拉仆从',Body=1396,Gender=3,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=10000,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1165,}",
  [8943] = "{id=8943,NameZh='格洛特',ShowName=2,Body=10232,Gender=2,BodyDefaultColor=0,Icon='Succubus',Desc='海拉的女侍从，看守死者之都南部所有的灵魂。对任何事物的反应都很迟钝，对海拉忠心耿耿。脾气不好十分危险，要避免与她正面冲突！',MoveSpdRate=1,DefaultDialog=109340,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1115,}",
  [8944] = "{id=8944,NameZh='格拉提',ShowName=2,Body=10065,Gender=3,BodyDefaultColor=0,Icon='Incubus',Desc='海拉的男侍从，看守死者之都北部所有的灵魂。做任何事都十分缓慢，能将一段饭吃上一天。常年被海拉嫌弃，有些自尊心受损，常被格洛特欺负。“你——好——啊——我——叫——格——拉——提。”——格拉提',MoveSpdRate=1,DefaultDialog=109341,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1169,}",
  [8945] = "{id=8945,NameZh='塞壬',ShowName=2,Body=1430,Gender=1,BodyDefaultColor=0,Icon='Seren_new',MoveSpdRate=1,DefaultDialog=107777,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Purikura='Sirens_d',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1038,}",
