  [8975] = "{id=8975,NameZh='格洛特',ShowName=2,Body=10232,Gender=2,BodyDefaultColor=0,Icon='Succubus',Desc='海拉的女侍从，看守死者之都南部所有的灵魂。对任何事物的反应都很迟钝，对海拉忠心耿耿。脾气不好十分危险，要避免与她正面冲突！',MoveSpdRate=1,DefaultDialog=109340,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1115,}",
  [8976] = "{id=8976,NameZh='格拉提',ShowName=2,Body=10065,Gender=3,BodyDefaultColor=0,Icon='Incubus',Desc='海拉的男侍从，看守死者之都北部所有的灵魂。做任何事都十分缓慢，能将一段饭吃上一天。常年被海拉嫌弃，有些自尊心受损，常被格洛特欺负。“你——好——啊——我——叫——格——拉——提。”——格拉提',MoveSpdRate=1,DefaultDialog=109341,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1169,}",
