  [8982] = "{id=8982,NameZh='海拉',ShowName=2,Position='死亡女神',Body=30061,Gender=2,BodyDefaultColor=0,Desc='海拉是统治死者之都尼夫海姆的死亡女神，也是魔狼芬里尔与尘世巨蟒耶梦加得的妹妹。虽然外表看起来是个小女孩，但绝对不要小看她的力量。意外的有着孩子气的一面，关于她的一切，对于人们来说依旧是个谜。',MoveSpdRate=1,DefaultDialog=601727,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Features=32,Purikura='Hella_2',PurikuraBG='Adventure_bg_NPC',DefaultRolePartID=1115,}",
