  [9128] = "{id=9128,NameZh='星痕',DisableWait=1,ShowName=1,Position='斐扬占卜师',Body=14,Eye=2,Gender=2,RightHand=40603,Hair=999,Head=45067,VisitVocal='Npc/XingHen_1-Npc/XingHen_4-Npc/XingHen_5',EndVocal='Npc/XingHen_2-Npc/XingHen_3',Desc='身为占卜师的她一直是斐扬的指引者，自从世代相传的水晶球碎裂后，就隐居于斐扬，专心教导下一任占卜师。',MoveSpdRate=1,DefaultDialog=131505,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1126,}",
