  [9133] = "{id=9133,NameZh='默德卡·兰尼',DisableWait=1,ShowName=1,Position='魔物学者',Body=1001,Gender=1,BodyDefaultColor=0,Hair=5,HeadDefaultColor=6,Head=45029,Icon='Man',MoveSpdRate=1,DefaultDialog=9949,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1032,}",
  [9134] = "{id=9134,NameZh='凯特莉娜',DisableWait=1,ShowName=1,Guild='魔法公会',GuildEmblem='icon_2_2',AtlasOpt='career',Position='天才巫师',Body=14,Eye=2,Gender=2,BodyDefaultColor=0,RightHand=40603,Hair=14,Head=145125,Desc='新进的天才少女巫师，有着极度自信的性格，不过这点经常会受到同伴们的不满，她自己本人并没有意识到这点。',MoveSpdRate=1,DefaultDialog=94027,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1159,}",
  [9135] = "{id=9135,NameZh='海陆曼',DisableWait=1,ShowName=1,Guild='皇家骑士团',GuildEmblem='icon_1_2',AtlasOpt='career',Position='团长',Body=1011,Gender=1,BodyDefaultColor=0,RightHand=400061,VisitVocal='Npc/Healueman_1-Npc/Healueman_2-Npc/Healueman_3',EndVocal='Npc/Healueman_4-Npc/Healueman_5-Npc/Healueman_6',Icon='NPC_Healueman',Desc='闻名大陆的皇家骑士团团长，以刚正不阿，超卓的战绩威震大陆，普隆德拉王国议会的核心成员之一。他一生从无败绩，对王国忠心耿耿，是普隆德拉的精神支柱之一。（日语CV：鳴海崇志）',MoveSpdRate=1,DefaultDialog=94022,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,Purikura='Hai Luman',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1033,}",
  [9136] = "{id=9136,NameZh='格丽塔',DisableWait=1,ShowName=1,Guild='皇家骑士团',GuildEmblem='career_01_2',AtlasOpt='guild',Position='副团长',Body=8,Eye=2,Gender=2,Hair=12,Head=45097,Mount=25101,VisitVocal='Npc/Greta_1-Npc/Greta_4',EndVocal='Npc/Greta_2-Npc/Greta_3',Desc='海陆曼对格丽塔的要求非常高，在执行任务时也是毫不留情的指派她去最危险的区域，但是在平时海陆曼也会送上格丽塔最爱喝的红茶，格丽塔非常的尊敬他。',MoveSpdRate=1,DefaultDialog=8930,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1087,}",
