  [9142] = "{id=9142,NameZh='贝尔蒙德·伊伦',DisableWait=1,ShowName=1,Position='吟游诗人',Body=1150,Gender=1,RightHand=400088,Hair=4,Head=400089,VisitVocal='Npc/Bard_1-Npc/Bard_2-Npc/Bard_4',EndVocal='Npc/Bard_3-Npc/Bard_5',Icon='GreenGleeman_1',Desc='随克雷斯特同盟军一起来到古城，自称是名吟游诗人的男子。他在半途被同盟军所救，自告奋勇来到古城，收集着被黑暗笼罩之地的传奇故事。衣着服装与其他吟游诗人不同，似乎是来自更遥远的国度。',MoveSpdRate=1,DefaultDialog=82092,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1076,}",
  [9143] = "{id=9143,NameZh='福金',DisableWait=1,ShowName=1,Body=1162,Gender=1,BodyDefaultColor=0,Hair=4,HeadDefaultColor=4,Icon='FullKing',Desc='专注于研究历史，考证古迹的学者。得到卢恩王国皇家许可，目前在米德加尔特各地考古。带着不少学徒，都是无家可归的流浪儿，他供学徒们衣食住宿，而学徒们则作为他的助手协助考古，逐渐这个考古队形成了一定规模，在米德加尔特极富盛名。',MoveSpdRate=1,DefaultDialog=81697,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,DefaultRolePartID=1012,}",
