  [9148] = "{id=9148,NameZh='艾丽维娅 ',DisableWait=1,ShowName=1,MapIcon='map_kapula',Position='卡普拉临时雇员',Body=20021,Gender=2,BodyDefaultColor=0,Icon='Alice',Desc='同盟军进驻古城后，卡普拉公司也决定在古城开设服务点，然而没有在职的卡普拉服务员愿意调到古城工作。于是经过海选招募，向往着进入卡普拉公司工作的热情女孩艾丽维娅终于有幸受雇，成为了古城常驻的卡普拉服务员。虽然是临时雇员，且工作环境恶劣，不过她依然热爱着这份工作。',MoveSpdRate=1,DefaultDialog=81733,NpcFunction={{type=3001}},IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1085,}",
