  [9958] = "{id=9958,NameZh='赛尼亚',ShowName=0,Body=4,Eye=2,Gender=2,BodyDefaultColor=0,RightHand=40301,Hair=14,HeadDefaultColor=7,Desc='最初的伙伴，爱好自由而四处流浪的剑士，旅行中与相遇的商人阿尔玛雅·娣洁一起遭遇雷根贝勒的毒手而成为被试验体。',MoveSpdRate=1,DefaultDialog=2051,IsVeer=1,move=0,AccessRange=2,Emoji=23,Action=9,Purikura='Seonia_S',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1148,}",
  [9959] = "{id=9959,NameZh='休朗克',ShowName=0,Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,VisitVocal='Npc/Xiulangke_2',EndVocal='Npc/Xiulangke_1-Npc/Xiulangke_3',Desc='一个豪迈的络腮胡大叔，健硕的肌肉上有着无数的伤痕和刀疤，仿佛在向冒险者倾诉他曾经的那些辉煌战果…',MoveSpdRate=1,DefaultDialog=2266,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,DefaultRolePartID=1026,}",
  [9960] = "{id=9960,NameZh='杜赫塔',ShowName=0,Body=13,Eye=1,Gender=1,BodyDefaultColor=0,RightHand=40603,Hair=8,Head=45067,VisitVocal='Npc/Duheta_1-Npc/Duheta_2',MoveSpdRate=1,DefaultDialog=2267,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1069,}",
  [9961] = "{id=9961,NameZh='伊丝米儿',DisablePlayshow=1,ShowName=0,Body=22,Eye=2,Gender=2,BodyDefaultColor=0,Hair=13,Head=45013,VisitVocal='Npc/Yisimier_1-Npc/Yisimier_2-Npc/Yisimier_3',Desc='将自己隐藏在黑暗中的女子，感觉不到一丝气息存在，是个背负着各种不祥传说的人。沉默寡言，等对方感觉到其杀气的时候已经离死亡不远了。',MoveSpdRate=1,DefaultDialog=2268,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,DefaultRolePartID=1114,}",
  [9962] = "{id=9962,NameZh='卡巴克',ShowName=0,Body=29,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45089,VisitVocal='Npc/Kabake_1-Npc/Kabake_2',Desc='穿着东方风的贵族气质男子，喜欢在下午优雅地喝着红茶。高高在上的皇家气质和某种说不出的奇怪气场让人觉得和其谈话压力甚大…',MoveSpdRate=1,DefaultDialog=2269,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,DefaultRolePartID=1012,}",
  [9963] = "{id=9963,NameZh='莱伊娜丝',ShowName=0,Body=40,Eye=2,Gender=2,BodyDefaultColor=0,Hair=14,Head=45081,VisitVocal='Npc/Laiyinasi_1-Npc/Laiyinasi_2-Npc/Laiyinasi_3',Desc='一位令人敬重的修女，从其身上能感受到圣母般的慈爱。对所有人都非常关爱，尤其对想转职为服事系的冒险者，会给予极大的帮助和指导。',MoveSpdRate=1,DefaultDialog=2270,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultRolePartID=1108,}",
