  [9971] = "{id=9971,NameZh='蛙王',ShowName=2,Race='Fish',Nature='Water',Body=10109,Gender=3,BodyDefaultColor=0,HeadDefaultColor=0,Icon='RodaFrog',Desc='罗达蛙的头目，对家族成员宠爱有加。拥有强健的体魄，有时会出水晒晒太阳保持健康的肤色。最看不惯的就是罗达蛙或达拉蛙被欺负，发现后一定对凶手严惩不贷！',Level=33,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,DefaultRolePartID=1163,}",
  [9972] = "{id=9972,NameZh='狂暴的达拉蛙',ShowName=2,Race='Fish',Nature='Water',Body=20006,Gender=1,BodyDefaultColor=0,HeadDefaultColor=0,Icon='Thara',Desc='罗达蛙的变异进化版，自从无意间得到人类遗留下的一台收音机后便热衷于收听米德加尔特王国的各类节目，偶尔靠近它还能听见其在认真地练习脱口秀。',DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=0,DefaultRolePartID=1018,}",
