  [800017] = "{id=800017,NameZh='贝鲁妮·托纳',ShowName=2,Position='清洁工',Body=1557,Gender=2,BodyDefaultColor=0,Hair=1370,Icon='House_cleaner2',AdventureSort=394,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='老帕特家的清洁工，心直口快性格很好。因为家庭成员众多，所以一直生活在贝勒区，生活拘谨节俭。',MoveSpdRate=2,DefaultDialog=305291,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Features=192,ManualMap=76,NpcWalk=7,DefaultRolePartID=1120,}",
