  [800024] = "{id=800024,NameZh='金',ShowName=2,Position='杰拉尔学徒',Body=394,Eye=2,Gender=2,BodyDefaultColor=0,Hair=58,HeadDefaultColor=6,Icon='College_F58',AdventureSort=393,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='从小父母双亡的少女，梅尔镇出生，凭借着努力跻身贝勒区。单纯幼稚但很真诚，杰拉尔看上了金观察事物的细心，却十分反感金的梦想。',MoveSpdRate=1,DefaultDialog=305298,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=76,DefaultRolePartID=1154,}",
  [800025] = "{id=800025,NameZh='杰拉尔',ShowName=2,Position='侦探',Body=1593,Gender=1,BodyDefaultColor=0,Icon='Detective',AdventureSort=392,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='自大自恋，嗜钱如命。贝勒区出生，但父母似乎是梅尔镇出生。不管怎样的案子，只要给钱杰拉尔先生都会帮你竭尽所能完成。无论是家里丢了猫还是老公偷了人，都瞒不住杰拉尔先生的慧眼。',MoveSpdRate=1,DefaultDialog=305299,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=76,Purikura='Geral',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1004,}",
