  [801643] = "{id=801643,NameZh='尤金·绵爪',ShowName=2,Guild='蝴蝶巡守队',GuildEmblem='butterflyteam',AtlasOpt='guild',Position='总考官',Body=1754,Gender=1,BodyDefaultColor=0,Icon='npcid801643',AdventureSort=51,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='蝴蝶巡守队的队长，在冒险考核中担任总考官。对待队员严厉又不失关爱。性格坚毅正直，再加上英俊的外表，在罗扎纳很有人气。',MoveSpdRate=1,DefaultDialog=400686,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=1.15,PlayShowActions={200},ManualMap=91,DefaultDialog_class1=400693,DefaultRolePartID=1027,}",
