  [803137] = "{id=803137,NameZh='维琪',DisablePlayshow=1,ShowName=2,Guild='乐园团',GuildEmblem='guild_03',AtlasOpt='guild',Position='教官',Body=715,Eye=46562,Gender=2,BodyDefaultColor=0,RightHand=40309,Hair=34,HeadDefaultColor=7,Wing=47129,Icon='Eden_F_1',Desc='前任乐园团教官宝雅的妹妹，与姐姐一起加入了乐园团。姐姐宝雅曾是南门最优秀的教官，引导着无数初心者成长为独当一面的冒险者。在抵御梦罗克入侵的战役中，宝雅主动请缨带领乐园团与其它的势力一起奋战。梦罗克最终被击退，但是宝雅却英勇牺牲。妹妹维琪为自己没能及时前往战场增援姐姐自责不已，她请辞了原来的职位，主动要求接替姐姐的工作成为新任教官。所有的初心者想要转职进阶的话都要通过维琪这一关，她和姐姐一样对新手非常严格，但是在关键时刻，她也会像姐姐一样挺身保护她的学生和这个世界。',MoveSpdRate=1,DefaultDialog=309807,IsVeer=0,move=0,AccessRange=2,Emoji=26,Action=9,Purikura='Vichy',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1131,}",
