  [803272] = "{id=803272,NameZh='安保员',DisablePlayshow=1,ShowName=2,Body=1619,Gender=1,Hair=7,HeadDefaultColor=3,Face=400144,MoveSpdRate=2,DefaultDialog=311601,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Features=192,DefaultRolePartID=1071,}",
  [803273] = "{id=803273,NameZh='辛格拉',ShowName=2,Position='宠物训练专家',Body=242,Eye=1,Gender=1,Hair=67,HeadDefaultColor=8,Icon='sindela',AdventureSort=397,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='辛格拉原本是个宠物训练专家。他经常出门溜溜他最得意的几只疾风小猎狐，每天都会路过镇上的那块委托看板。闲来无事，他也就看看看板上的那些委托。不仅赏金少，做的事也是够无聊的。他如此想到。也是，一些真正困扰人的事，谁会大张旗鼓地贴在人来人往的地方呢。他一边想着，一边看着自己那些有着无限精力的疾风小猎狐。嗯？他灵光一闪。不如……从那天以后，里希塔乐镇上就多了一只提着手提箱的疾风小猎狐和一个委托邮箱。任何人有悬赏委托都可以投入邮箱里，辛格拉每天都会将这些委托整理好放入疾风小猎狐的手提箱里，供强大的却又缺钱的冒险者们选择，并从中赚取差价。似乎还挺受欢迎的。呼呼~收入还不错！我可要把这个事业再做大一点！',MoveSpdRate=1,DefaultDialog=311602,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=0,ManualMap=76,DefaultRolePartID=1030,}",
  [803274] = "{id=803274,NameZh='委托收集箱',DisableWait=1,DisablePlayshow=1,ShowName=2,Body=1078,Gender=4,Icon='803274',MoveSpdRate=1,DefaultDialog=311603,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=0.5,Features=32,ShadowCastOff=1,DefaultRolePartID=1170,}",
