  [803277] = "{id=803277,NameZh='罗意威',ShowName=2,Position='研究者',Body=217,Eye=1,Gender=1,Hair=42,HeadDefaultColor=3,AdventureSort=395,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='雷根贝勒公司外聘的研究者，崇尚科学的力量。相信雷根贝勒公司的科技能为人类带来新的未来，盲目的乐观主义者。',MoveSpdRate=1,DefaultDialog=311617,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=76,DefaultRolePartID=1029,}",
