  [803282] = "{id=803282,NameZh='托格隆',ShowName=2,Position='修理工',Body=1264,Gender=1,Icon='Elder_M',AdventureSort=400,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='作为掌握工业跃进时期手艺的老牌修理工，拖格隆在这几年来一直致力于培养学徒，常抱怨现在的年轻人不能吃苦没有毅力。拖格隆的心愿是修理好梅尔区的火车，为在这里生活的人们争取到物资与希望。',MoveSpdRate=1,DefaultDialog=311622,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=76,DefaultRolePartID=1041,}",
  [803283] = "{id=803283,NameZh='艾琳',ShowName=2,Position='贝勒大酒店',Body=1252,Eye=1,Gender=2,Hair=53,HeadDefaultColor=9,Icon='803283',AdventureSort=396,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='梅尔区出身的贝勒大酒店接待员，虽然每天辛苦劳碌，但仍心怀着梦想——总有一天，我会开一间比贝勒大酒店更棒的酒店！',MoveSpdRate=1,DefaultDialog=311627,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=76,DefaultRolePartID=1127,}",
