  [803660] = "{id=803660,NameZh='吱吱',DisablePlayshow=1,ShowName=2,Position='贪吃的松鼠',Body=10340,Gender=3,MoveSpdRate=3,DefaultDialog=450605,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.2,DefaultRolePartID=1167,}",
  [803661] = "{id=803661,NameZh='嘉莉·布蕾',DisablePlayshow=1,ShowName=2,Body=300,Eye=3,Gender=2,Hair=82,HeadDefaultColor=9,Head=45646,AdventureSort=58,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='居住在罗比奥森林里的猫咪女巫，沉默寡言的冰山美喵。泪之湖的看守人，掌握着多兰族记忆的钥匙。性格冷淡疏离，但意外的容易害羞，并不怎么会拒绝别人。',MoveSpdRate=2,DefaultDialog=450606,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ManualMap=93,Purikura='Jali',PurikuraBG='Adventure_bg_NPC2',BodyChangeColor=13,DefaultRolePartID=1134,}",
  [803662] = "{id=803662,NameZh='波拉',DisablePlayshow=1,ShowName=2,Position='记忆守护者',Body=1761,Gender=3,Icon='npcid803662',AdventureSort=60,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='住在着泪之湖底的塔鲁圆皮龙，是猫猫们记忆的守护者。天然呆，平时懒洋洋的，只有食物可以让他提起精神。说话有口癖，会自称“咱”。和女巫嘉莉的关系很好。',MoveSpdRate=3,DefaultDialog=450607,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ManualMap=93,Purikura='Taul_dragon',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1165,}",
