  [803735] = "{id=803735,NameZh='艾比·慕斯',DisablePlayshow=1,ShowName=2,Body=224,Eye=3,Gender=1,Hair=96,HeadDefaultColor=8,Head=45920,Wing=47019,AdventureSort=57,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='机灵活泼的猫咪少年。人缘很好，到处都有他的朋友。满怀好奇心，看起来不太稳重，但观察与分析能力一流。特长是做蛋糕。',MoveSpdRate=2,DefaultDialog=450316,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,NoShowIcon=1,ManualMap=91,Purikura='Aibi',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1054,}",
  [803736] = "{id=803736,NameZh='嘉莉·布蕾',DisablePlayshow=1,ShowName=2,Body=300,Eye=3,Gender=2,Hair=82,HeadDefaultColor=9,Head=45646,Desc='居住在罗比奥森林里的猫咪女巫，沉默寡言的冰山美喵。泪之湖的看守人，掌握着多兰族记忆的钥匙。性格冷淡疏离，但意外的容易害羞，并不怎么会拒绝别人。',MoveSpdRate=2,DefaultDialog=450606,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,NoShowIcon=1,Purikura='Jali',PurikuraBG='Adventure_bg_NPC2',BodyChangeColor=13,DefaultRolePartID=1134,}",
