  [803739] = "{id=803739,NameZh='杰克',ShowName=2,Guild='康奇丽娜号',GuildEmblem='guild_06',AtlasOpt='guild',Position='船长',Body=1757,Gender=1,BodyDefaultColor=0,Icon='npcid801640',Desc='康奇丽娜号的船长，经验丰富的航海家。总是一脸不高兴的样子，其实是个傲娇。和多拉贡是老朋友，曾经是海上的黄金搭档。',MoveSpdRate=1,DefaultDialog=400651,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=91,DefaultDialog_class1=400683,DefaultRolePartID=1055,}",
  [803740] = "{id=803740,NameZh='波拉',DisablePlayshow=1,ShowName=2,Position='记忆守护者',Body=1761,Gender=3,Icon='npcid803662',Desc='住在着泪之湖底的塔鲁圆皮龙，是猫猫们记忆的守护者。天然呆，平时懒洋洋的，只有食物可以让他提起精神。说话有口癖，会自称“咱”。和女巫嘉莉的关系很好。',MoveSpdRate=3,DefaultDialog=450607,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Purikura='Taul_dragon',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1165,}",
