  [804011] = "{id=804011,NameZh='托马斯',ShowName=2,Position='列车长',Body=277,Eye=1,Gender=1,Hair=63,HeadDefaultColor=3,Head=400173,Mouth=48638,Icon='804011',AdventureSort=399,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='这个男人永远以列车长自称，恐怕连他本人都忘记了自己的原名。从小喜欢火车的他看着火车站建起，又亲眼看着它被废弃。离开家乡后，列车长前往朱诺学习载具的驾驶技术。对于执着于火车之梦他来说，火车是他的爱人，他的生命。当他得知自己被调到自己的故乡梅尔区成为列车长后，他义无反顾的回到了里希塔乐。我们可以知道的是，无论今后火车能否被修复，他都会一辈子守候在这里。',MoveSpdRate=1,DefaultDialog=311739,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=76,Purikura='Train_conductor',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1071,}",
