  [806105] = "{id=806105,NameZh='莱特·托纳',ShowName=2,Position='托纳家长子',Body=1555,Gender=1,BodyDefaultColor=0,Icon='Maku',Desc='贝鲁妮的儿子，非常宠爱妹妹，火车修理员。梦想是修好火车，带着全家人离开这里。',MoveSpdRate=2,DefaultDialog=305312,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Features=192,Purikura='Wrightoner',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1020,}",
