  [806180] = "{id=806180,NameZh='杰拉尔',ShowName=2,Position='侦探',Body=1593,Gender=1,BodyDefaultColor=0,Icon='Detective',Desc='自大自恋，嗜钱如命。贝勒区出生，但父母似乎是梅尔镇出生。不管怎样的案子，只要给钱杰拉尔先生都会帮你竭尽所能完成。无论是家里丢了猫还是老公偷了人，都瞒不住杰拉尔先生的慧眼。',MoveSpdRate=1,DefaultDialog=305299,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Purikura='Geral',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1004,}",
