  [806724] = "{id=806724,NameZh='柯林特',ShowName=2,MapIcon='map_kapula',Position='准它公司职员',Body=1807,Gender=1,BodyDefaultColor=0,Hair=2,HeadDefaultColor=8,Face=48717,MoveSpdRate=1,DefaultDialog=550311,NpcFunction={{type=8204},{type=8206},{type=8201},{type=8205},{type=3001}},FnIcon='66',FnDesc='仓库/存储/传送',IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1008,}",
  [806725] = "{id=806725,NameZh='赫卡利',ShowName=2,Body=1,Eye=1,EyeDefaultColor=1,Gender=1,BodyDefaultColor=0,Hair=6,AdventureSort=408,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='初出茅庐的冒险者，对一切事物充满好奇心，虽然莽撞，但是带有一些学者派的书卷气，待人和善。',MoveSpdRate=1,DefaultDialog=550296,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=83,DefaultRolePartID=1008,}",
  [806726] = "{id=806726,NameZh='玛丽娅',ShowName=2,Body=1265,Gender=2,BodyDefaultColor=0,Icon='Elder_F',AdventureSort=409,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='西尔比的姐姐，有着轻微的洁癖，看起来是个精明能干的大姐姐，但西尔比认为她就是个傻大姐。',MoveSpdRate=1,DefaultDialog=550297,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=83,DefaultRolePartID=1143,}",
  [806727] = "{id=806727,NameZh='西尔比',ShowName=2,Body=1101,Gender=1,BodyDefaultColor=0,Hair=20,HeadDefaultColor=9,Icon='Woman209',AdventureSort=410,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='玛丽娅的妹妹，自称是百年难得一见的大预言家，爱好是帮助自己的占卜对象解决烦恼，由于过于热情而为其他居民造成了一些困扰。',MoveSpdRate=1,DefaultDialog=550298,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=83,DefaultRolePartID=1012,}",
  [806728] = "{id=806728,NameZh='德拉坎',ShowName=2,Body=1093,Gender=1,BodyDefaultColor=0,Icon='Adventurer_F',AdventureSort=411,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='学识渊博的地质学家，非常热爱大自然，对于平原上的贫瘠状况十分上心，想要通过努力让伊达平原丰饶起来。',MoveSpdRate=1,DefaultDialog=550299,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=83,DefaultRolePartID=1064,}",
  [806729] = "{id=806729,NameZh='艾希欧',ShowName=2,Body=78,Eye=2,EyeDefaultColor=2,Gender=2,BodyDefaultColor=0,RightHand=41207,Hair=34,HeadDefaultColor=8,AdventureSort=412,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='为了磨练自己而决定在冰洞中定居的少女，性格比男人更加坚强果敢，不论是什么困难都会勇敢的面对，因此吸引了不少拥趸。',MoveSpdRate=1,DefaultDialog=550300,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=84,DefaultRolePartID=1089,}",
  [806730] = "{id=806730,NameZh='泰米尔',ShowName=2,Body=77,Eye=1,EyeDefaultColor=1,Gender=1,BodyDefaultColor=0,Hair=23,HeadDefaultColor=8,AdventureSort=413,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='“朴实”是大多数人对泰米尔的评价，但这样的他却突然决定来到冰洞，似乎是有什么特殊的原因......',MoveSpdRate=1,DefaultDialog=550301,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=84,DefaultRolePartID=1020,}",
  [806731] = "{id=806731,NameZh='莱特米',ShowName=2,Body=1021,Gender=1,BodyDefaultColor=0,Icon='Juno_Ambassador',AdventureSort=414,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='年轻有为的建筑师，在建筑领域有着很高的造诣，无论是什么恶劣的环境，他都有信心造出能让人居住舒适的房子。',MoveSpdRate=1,DefaultDialog=550302,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=84,DefaultRolePartID=1056,}",
  [806732] = "{id=806732,NameZh='维尼亚',ShowName=2,Body=34,Eye=2,EyeDefaultColor=2,Gender=2,BodyDefaultColor=0,Hair=52,HeadDefaultColor=7,AdventureSort=415,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='家境殷实的大小姐，心中充满了对花花世界的向往，总是会冒出一些不切实际的想法，但也像普通女孩一样喜欢可爱、美丽的事物。',MoveSpdRate=1,DefaultDialog=550303,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=84,DefaultRolePartID=1082,}",
  [806733] = "{id=806733,NameZh='迪塔斯',ShowName=2,Body=1008,Gender=1,BodyDefaultColor=0,RightHand=40059,Hair=41,HeadDefaultColor=5,Icon='Guard415',AdventureSort=416,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='本尼的弟弟，拉赫的民兵队长，心中有着很强的正义感，誓言要不惜一切保护拉赫，也因此有些暴躁和莽撞。',MoveSpdRate=1,DefaultDialog=550304,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=87,DefaultRolePartID=1005,}",
  [806734] = "{id=806734,NameZh='本尼',ShowName=2,Body=1014,Gender=1,BodyDefaultColor=0,Hair=7,HeadDefaultColor=5,Icon='Equipmaster75',AdventureSort=417,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='迪塔斯的哥哥，辅助弟弟进行神殿地下的探查工作，心思细腻，充满智慧，很关心本尼。',MoveSpdRate=1,DefaultDialog=550305,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=87,DefaultRolePartID=1041,}",
  [806735] = "{id=806735,NameZh='格罗斯',ShowName=2,Body=1022,Gender=1,BodyDefaultColor=0,Icon='Rune_Ambassador',AdventureSort=418,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='专精于魔物的研究者，对于魔物以及魔物相关的事情有着超乎常人的热情，这让旁人对他议论纷纷，但他仍执着的进行着自己的研究。',MoveSpdRate=1,DefaultDialog=550306,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=87,DefaultRolePartID=1068,}",
  [806736] = "{id=806736,NameZh='卡兹',ShowName=2,Body=1014,Gender=1,BodyDefaultColor=0,Hair=26,HeadDefaultColor=3,Icon='Equipmaster263',AdventureSort=419,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='技艺高超的工匠大师，民兵队的装备多由他负责打造，同时他也拥有不俗的身手，常常为了收集铸造用的素材深入险地。',MoveSpdRate=1,DefaultDialog=550307,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,ManualMap=87,DefaultRolePartID=1001,}",
