  [806778] = "{id=806778,NameZh='托兰西',ShowName=2,Body=1805,Gender=1,BodyDefaultColor=0,Icon='Rachel_child_A',AdventureSort=403,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='热爱歌唱的音乐神童托兰西，三岁时就可以自己编写乐谱，演奏出的曲子十分受人欢迎，是拉赫最小的演奏家，但是由于出身卑微，一直无缘加入拉赫最著名的唱诗班——乐贝塔儿童合唱团。',MoveSpdRate=0.7,DefaultDialog=550347,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,Features=96,ManualMap=85,DefaultRolePartID=1062,}",
