  [806783] = "{id=806783,NameZh='路克斯',ShowName=1,Body=1744,Gender=1,BodyDefaultColor=0,Hair=1388,HeadDefaultColor=3,Head=400209,MoveSpdRate=1.3,DefaultDialog=550348,IsVeer=1,move=0,AccessRange=2,NoShowIcon=1,Scale=1.2,LoadShowSize=1,LoadShowPose={0,0,0},Features=96,Purikura='lux_drawinig',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1021,}",
  [806784] = "{id=806784,NameZh='安妮尔',ShowName=2,Body=1807,Gender=1,BodyDefaultColor=0,Hair=4,HeadDefaultColor=3,Icon='806784',AdventureSort=405,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='安尼尔是拉赫的大神官奥兰多之子，奥兰多曾是教国圣母的心腹，是最受圣母信任的大神官，但是不知发生了什么，奥兰多却突然销声匿迹，安尼尔思念自己的父亲，不停的向圣母祈祷，只求能再见父亲一面。',MoveSpdRate=1,DefaultDialog=550349,IsVeer=0,move=0,AccessRange=2,NoShowIcon=1,Features=96,ManualMap=85,DefaultRolePartID=1014,}",
  [806785] = "{id=806785,NameZh='库雷娜',ShowName=2,Body=1746,Gender=2,BodyDefaultColor=0,Hair=15,HeadDefaultColor=8,Icon='806785',AdventureSort=406,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='库雷娜的记忆里有一座大船，一群孩子穿着破旧的衣服拥挤地蜷缩在甲板上，库雷娜就是其中之一，后来海上发生了海啸，库雷娜被冲到了岸上，一位主教救了她，那是她生命里的光，她愿意永远跟随它。',MoveSpdRate=1,DefaultDialog=550350,IsVeer=0,move=0,AccessRange=2,NoShowIcon=1,Features=96,ManualMap=85,DefaultRolePartID=1121,}",
  [806786] = "{id=806786,NameZh='奎尔杰琳',ShowName=2,Body=42,Eye=2,Gender=2,BodyDefaultColor=0,Hair=15,HeadDefaultColor=6,Head=145284,AdventureSort=407,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='神历15日，教国与王国的战争再次开始了，他听从教皇的旨意前往了战场。神历27日，白鸽送来了书信，证明他一切安好。神历48日，我已经很久没有看到白鸽的羽翼了……女神啊，您可否听到我呼唤，请您庇佑我所爱之人，让我们可以再次相拥吧。',MoveSpdRate=1,DefaultDialog=550351,IsVeer=0,move=0,AccessRange=2,NoShowIcon=1,Features=96,ManualMap=85,BodyChangeColor=13,DefaultRolePartID=1098,}",
