  [806918] = "{id=806918,NameZh='卡普拉服务人员',ShowName=2,MapIcon='map_kapula',Body=1760,Gender=2,BodyDefaultColor=0,Icon='npcid801609',MoveSpdRate=1,DefaultDialog=601243,NpcFunction={{type=3001}},FnIcon='94',FnDesc='安全地带传送',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,Scale=1.2,Purikura='Kafra_cat',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1097,}",
  [806919] = "{id=806919,NameZh='悉多·绵爪',ShowName=2,Position='“康奇丽娜号”船员',Body=224,Eye=3,Gender=1,Hair=95,HeadDefaultColor=3,AdventureSort=61,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='康奇丽娜号的船员，看起来不太聪明。明明很害怕杰克船长，但也不知道是哪里来的勇气，经常溜下船开小差。',MoveSpdRate=1,DefaultDialog=600904,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=92,DefaultRolePartID=1009,}",
  [806920] = "{id=806920,NameZh='乔·绵爪',ShowName=2,Position='海岛管理员',Body=299,Eye=3,Gender=1,Hair=84,HeadDefaultColor=2,AdventureSort=62,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='多拉贡岛的管理员。在岛上呆了许多年，热爱这里的一切。最近在研究海岛垃圾分类，对随地乱丢废弃物的冒险者会很严厉。',MoveSpdRate=1,DefaultDialog=600908,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=92,DefaultRolePartID=1073,}",
  [806921] = "{id=806921,NameZh='道林·绵爪',ShowName=2,Position='灯塔瞭望员',Body=1753,Gender=1,Icon='npcid801602',AdventureSort=63,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='多拉贡岛上灯塔的瞭望员。对海洋有很深的执念，工作之余喜欢去沙滩边看着远处的行船。是个挺浪漫的家伙，有空还会自己写写诗。',MoveSpdRate=1,DefaultDialog=600912,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=92,DefaultRolePartID=1040,}",
  [806930] = "{id=806930,NameZh='海陆曼',ShowName=2,Guild='皇家骑士团',GuildEmblem='icon_1_2',AtlasOpt='career',Position='团长',Body=1011,Gender=1,BodyDefaultColor=0,RightHand=400061,Icon='NPC_Healueman',MoveSpdRate=1,DefaultDialog=94022,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,Purikura='Hai Luman',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1033,}",
  [806931] = "{id=806931,NameZh='路克斯',ShowName=2,Body=1744,Gender=1,Hair=1388,Icon='806931',AdventureSort=404,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='权利的顶端，无上的王者，阿卢纳贝兹新一任的教皇——路克斯·耶尔·露格尼卡。“神明的预言究竟是祝福还是诅咒？我们所坚持的真的是正确的么？这教皇的权杖还真是烫手呢……”',MoveSpdRate=1.3,DefaultDialog=500928,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Scale=1.2,LoadShowSize=1,LoadShowPose={0,0,0},ManualMap=85,Purikura='lux_drawinig',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1021,}",
  [806932] = "{id=806932,NameZh='莎缇拉',ShowName=2,Body=1742,Gender=2,Hair=1386,MoveSpdRate=1.3,DefaultDialog=500929,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Scale=1.2,Purikura='Girl_pope',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1091,}",
