  [807002] = "{id=807002,NameZh='埃尔文·雪耳',ShowName=2,Position='森林观察员',Body=224,Eye=3,Gender=1,Hair=93,AdventureSort=59,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='远星大陆的自然观察员，为了研究奇异的巨蛋而住在了罗比奥森林里。爽朗阳光的猫咪叔叔，对待研究充满热情。',MoveSpdRate=1,DefaultDialog=600921,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=93,DefaultRolePartID=1014,}",
  [807003] = "{id=807003,NameZh='波拉',ShowName=2,Position='记忆守护者',Body=1761,Gender=3,Icon='npcid803662',Desc='住在着泪之湖底的塔鲁圆皮龙，是猫猫们记忆的守护者。天然呆，平时懒洋洋的，只有食物可以让他提起精神。说话有口癖，会自称“咱”。和女巫嘉莉的关系很好。',MoveSpdRate=1,DefaultDialog=600925,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=2,Purikura='Taul_dragon',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1165,}",
