  [807380] = "{id=807380,NameZh='卡米',ShowName=2,Body=1907,Gender=2,Hair=1394,Icon='Dragon_F',AdventureSort=423,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='卡米是洛阳城知识最渊博的女性，她认为个体的价值不应该只看外表和能力，更应该关注品德和修养。法海非常赞同她的观念，选择卡米成为挑选花魁的主持人，为洛阳城挑选出杰出的女性，树立正确的价值。卡米所选出的花魁，也许不是最美的，也许不是魔法最精妙的，但一定是心地善良的。这也是卡米自己的处世之道。',MoveSpdRate=1,DefaultDialog=502280,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,ManualMap=99,DefaultRolePartID=1144,}",
