  [808041] = "{id=808041,NameZh='雷藏',DisablePlayshow=1,ShowName=2,Guild='魔法公会',GuildEmblem='icon_2_2',AtlasOpt='career',Body=1118,Gender=1,RightHand=40620,Hair=1105,Head=400147,Icon='NPC_LighttingCast',Desc='来自吉芬城的贵族魔法师，在魔法的海洋中拥有无与伦比的天赋，是有史以来最天才的魔法师之一，为人古板，视吉芬与魔法公会为一切，如今已经是城中有数的强者，镇守在吉芬城。',MoveSpdRate=1,DefaultDialog=8870,IsVeer=1,move=0,AccessRange=2,Emoji=12,Action=9,Purikura='Raizan',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1046,}",
