  [808043] = "{id=808043,NameZh='庞德',DisablePlayshow=1,ShowName=2,Body=1,Eye=1,Gender=1,Hair=2,HeadDefaultColor=2,Head=45107,Desc='从小就法师要成为一名出色的魔法师，在冒险者的帮助下成功的进入到了吉芬的魔法学院，最喜欢依斯鲁得的黄昏，那里有他儿时的影子。',MoveSpdRate=1,DefaultDialog=92032,IsVeer=1,AccessRange=2,Emoji=24,Action=9,DefaultRolePartID=1005,}",
  [808044] = "{id=808044,NameZh='凯特莉娜',DisablePlayshow=1,ShowName=2,Guild='魔法公会',GuildEmblem='icon_2_2',AtlasOpt='career',Position='天才巫师',Body=14,Eye=2,Gender=2,BodyDefaultColor=0,RightHand=40603,Hair=14,Head=145125,Desc='新进的天才少女巫师，有着极度自信的性格，不过这点经常会受到同伴们的不满，她自己本人并没有意识到这点。',MoveSpdRate=1,DefaultDialog=94027,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1159,}",
