  [808063] = "{id=808063,NameZh='许仙',DisablePlayshow=1,ShowName=2,Position='洛阳城主',Body=1898,Gender=1,Icon='XuXian',AdventureSort=420,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='洛阳城主许仙，一个出身在银鱼湖底，神圣之花中的男人。在许仙出生的那天，法海抱着他出现在洛阳所有居民前，就向所有人宣布怀中的孩子会成为洛阳的主人。他在平静又繁荣的洛阳城度过了500年的快乐生活，没有辜负大家的希望，成为一个负责任的城主，虽然有时候会有些调皮。',MoveSpdRate=1,DefaultDialog=603558,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=0,Scale=1.1,LoadShowSize=0.9,LoadShowPose={0,-0.2,0},ManualMap=99,Purikura='XuXian_umbrella',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1049,}",
  [808064] = "{id=808064,NameZh='法海',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫指挥使',Body=1903,Gender=1,Icon='FaHai',Desc='法海是洛阳城法纳族的领袖，也是洛阳安保机构影枫司的领导者。他性格沉静，头脑睿智，是全洛阳人心目中的英雄。法海的父亲是龙神古恩的好友裴休，母亲的种族是洛阳的迷。有传言说法海的母亲是来自深渊的恶魔，也有传言说，法海有古代神族的血统。这也为法海添加了一丝神秘的气质，这个有着银色长发的法纳族男人也是洛阳女妖心里的梦中情人。',MoveSpdRate=1,DefaultDialog=603559,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.2,LoadShowSize=0.9,LoadShowPose={0,-0.2,0},Purikura='FaHai',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1013,}",
  [808065] = "{id=808065,NameZh='平安',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫',Body=1904,Gender=1,Icon='Trooper_M',AdventureSort=421,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='影枫司最年轻的锦衣卫，有人说平安就像年轻的法海一样，充满朝气和希望。平安也是这样对自己说的，他会成为继古恩法海之后，洛阳下一代守护者！为了达成这个目标，平安日夜修炼自己的魔法和武艺，最终成为法海身边最得力的助手。平安还有着一颗善良的心，经常无私的帮助身边的人。洛阳城的居民都很喜欢这个年轻又出色的法纳族！',MoveSpdRate=1.4,DefaultDialog=603560,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=99,Purikura='Trooper_M',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1072,}",
