  [808081] = "{id=808081,NameZh='客房柜子',DisablePlayshow=1,ShowName=1,Body=1928,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=601561,IsVeer=0,move=1,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Features=32,ShadowCastOff=1,DefaultRolePartID=1170,}",
  [808082] = "{id=808082,NameZh='古恩',DisablePlayshow=1,ShowName=2,Position='巨龙人身',Body=2031,Gender=1,BodyDefaultColor=0,Face=48734,Icon='YingTian',AdventureSort=436,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='传说中，远古的巨人伊米尔有一颗慈悲的心，他时常躲在虚空中注视着九大世界的运转，帮助各个种族繁荣生长。他经常久久地凝望洛阳和他亲手创造的法纳族，其中最出色的人就是古恩。古恩有着不逊于战神的远古巨龙之力，不输于伊米尔的慈悲之心。千年前，他为了保护洛阳，牺牲自己的身体和自由，化身巨龙，斩断时空的连接，让洛阳脱离九大世界的时空。现如今，他依然用自己庞大的龙身缠绕着洛阳的流之云边，在高山之上遥望洛阳城的居民。',MoveSpdRate=1,DefaultDialog=603563,IsVeer=0,move=1,AccessRange=2,Emoji=0,Action=0,Scale=1.2,LoadShowSize=0.85,LoadShowPose={0,-0.2,0},ManualMap=99,DefaultRolePartID=1015,}",
