  [808112] = "{id=808112,NameZh='小青',DisablePlayshow=1,ShowName=2,Position='花楼老板',Body=1902,Gender=2,Icon='XiaoQing',AdventureSort=430,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='出身于花楼之中，毒牙少女小青从小就见惯了男女之间的爱恨情仇。她的母亲，曾经是名满洛阳的花魁，多少洛阳的富家子弟愿意花无数的财富只为了见上一面！也许，美神也嫉妒小青母亲的美貌，让她年纪轻轻就患病离世。同样是孤儿的白素贞可怜小青，承担了抚养小青的责任，伴随她一路成长。长大的小青继承了母亲的美貌，也摒弃了母亲多愁善感的性格，成为花楼当家的主人。',MoveSpdRate=1,DefaultDialog=603564,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=100,DefaultRolePartID=1081,}",
