  [808246] = "{id=808246,NameZh='法海',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫指挥使',Body=1903,Gender=1,Icon='FaHai',AdventureSort=435,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='法海是洛阳城法纳族的领袖，也是洛阳安保机构影枫司的领导者。他性格沉静，头脑睿智，是全洛阳人心目中的英雄。法海的父亲是龙神古恩的好友裴休，母亲的种族是洛阳的迷。有传言说法海的母亲是来自深渊的恶魔，也有传言说，法海有古代神族的血统。这也为法海添加了一丝神秘的气质，这个有着银色长发的法纳族男人也是洛阳女妖心里的梦中情人。',MoveSpdRate=1,DefaultDialog=603586,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,Scale=1.2,LoadShowSize=0.9,LoadShowPose={0,-0.2,0},ManualMap=99,Purikura='FaHai',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1013,}",
  [808247] = "{id=808247,NameZh='裂隙',DisablePlayshow=1,ShowName=1,Body=1596,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=601755,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ShadowCastOff=1,DefaultRolePartID=1171,}",
  [808248] = "{id=808248,NameZh='钱娘',DisablePlayshow=1,ShowName=2,Body=10301,Gender=2,Icon='Miyabi_10',Desc='花楼有个特别的舞女，名字叫做钱娘。据传言说，她原本是洛阳出名的魔法大师，她跟自己的恋人一起建立了一座法师塔，常年在塔里研究魔法的奥秘！因为跟恋人在魔法理念上有些不同，前娘生气地跑到花楼喝酒消愁，与老板小青相识成为了朋友。在花楼的这段日子，让钱娘明白，身处在高塔研究地魔法永远是理论，只有在群众里生活才能明白魔法真正的奥秘，为了能贴近人群，研究洛阳人真正需要的法术，她长年客居花楼。偶尔，她也会因为心情比较好，为其他客人跳跳舞。大家只知道，花楼有个高傲地舞女钱娘，却不知道这个舞女也是洛阳许多魔法的创造人！',MoveSpdRate=1,DefaultDialog=502281,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1126,}",
  [808249] = "{id=808249,NameZh='法海',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫指挥使',Body=1903,Gender=1,Icon='FaHai',Desc='法海是洛阳城法纳族的领袖，也是洛阳安保机构影枫司的领导者。他性格沉静，头脑睿智，是全洛阳人心目中的英雄。法海的父亲是龙神古恩的好友裴休，母亲的种族是洛阳的迷。有传言说法海的母亲是来自深渊的恶魔，也有传言说，法海有古代神族的血统。这也为法海添加了一丝神秘的气质，这个有着银色长发的法纳族男人也是洛阳女妖心里的梦中情人。',MoveSpdRate=1,DefaultDialog=603559,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.1,Purikura='FaHai',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1013,}",
