  [808355] = "{id=808355,NameZh='探秘人',ShowName=2,Body=1908,Gender=1,BodyDefaultColor=0,Icon='811151',Desc='身份成谜的古怪男子。没人知道他是谁，也没人知道他为什么在这里。脾气古怪，似乎知道荒境所有的秘密。',MoveSpdRate=1,DefaultDialog=604066,NpcFunction={{type=10109},{type=10110}},IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1062,}",
