  [808357] = "{id=808357,NameZh='白素贞',DisablePlayshow=1,ShowName=2,Body=1900,Gender=2,Icon='BaiSuzhen',Desc='花容月貌和神秘的身世让白素贞成为一个复杂的女人，只有在脆弱的时刻，她才会对亲近信赖的人透露自己内心的秘密。灯火大会与许仙的相遇，成功突破她内心的防线，让她被冰冻的内心开始动摇，爱情的嫩芽开始从她的心底长了出来。她不希望自己的感情影响自己的计划，却又无克制地想要靠近许仙…',MoveSpdRate=2,DefaultDialog=603584,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.1,Purikura='BaiSuzhen',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1127,}",
