  [809035] = "{id=809035,NameZh='普莱',DisablePlayshow=1,ShowName=2,Body=2035,Gender=1,Hair=1392,HeadDefaultColor=3,Icon='809035',AdventureSort=422,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='据说法纳族是严肃认真的种族，而成为锦衣卫的法纳族更是一丝不苟又沉默寡言。莱普可能是锦衣卫中的异类，他是天生的乐观派，喜欢跟毒牙族一块喝酒作乐，有时候还会带着城主许仙到处恶作剧！所有锦衣卫都害怕法海，只有莱普会对着法海勾肩搭背，还邀请法海去花楼喝酒。这大概就是粗线条吧！',MoveSpdRate=1,DefaultDialog=460012,IsVeer=1,move=0,AccessRange=2,Emoji=22,Action=9,ManualMap=99,DefaultRolePartID=1010,}",
