  [809066] = "{id=809066,NameZh='薇安',ShowName=2,Position='湖鬼',Body=30088,Gender=1,Icon='cardhead_20037',AdventureSort=424,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='薇安是现任银鱼湖主人的小妹妹，也是整个湖底精怪们都喜欢的小公主。她一直自由自在的生活在湖底，没有任何烦恼和忧愁。直到有一天，小人鱼带着薇安去洛阳灯会凑热闹，那天她在靠近水草的角落，看见了让自己一生发生改变的人—法海。从此银鱼湖少了一位小公主，影枫司旁边多了个经常恶作剧的小妖怪。',MoveSpdRate=1,DefaultDialog=460024,IsVeer=1,move=0,AccessRange=2,Emoji=22,Action=9,Hide=1,LoadShowPose={0,-0.4,0},ManualMap=99,DefaultRolePartID=1018,}",
