  [809076] = "{id=809076,NameZh='西索尔',DisablePlayshow=1,ShowName=0,Body=1908,Gender=2,BodyDefaultColor=0,Icon='Serpent_M',MoveSpdRate=1,DefaultDialog=482345,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NpcWalk=2407,BodyChangeColor=1,DefaultRolePartID=1113,}",
  [809077] = "{id=809077,NameZh='提曼',DisablePlayshow=1,ShowName=0,Position='茶铺老板',Body=1906,Gender=1,BodyDefaultColor=2,Hair=1393,Icon='Dragon_M',AdventureSort=428,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='洛阳城擅长制作茶叶的商人非常多，有些对种茶很讲究，有些擅长烘培和烤制茶叶。只有提曼对泡茶所用的水最在意了！他曾经走遍洛阳的山村乡野，在高山里寻找清澈透明的溪流，用不同地方的水泡制茶叶。最终，他找到最适合泡茶的水源和温度，他对茶叶的热爱，对极致的追求也让他成为洛阳一代制茶大师。',MoveSpdRate=1,DefaultDialog=481220,IsVeer=1,move=0,AccessRange=4,Emoji=0,Action=0,Features=32,ManualMap=100,NpcWalk=2406,DefaultRolePartID=1016,}",
  [809078] = "{id=809078,NameZh='赛利',DisablePlayshow=1,ShowName=2,Position='画摊老板',Body=1908,Gender=2,BodyDefaultColor=0,Icon='Serpent_M',AdventureSort=427,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='很多洛阳人都觉得，法纳族男性是不可能学会绘画的，因为他们宽大的手指和尖锐的指甲让他们缺少天生优势。赛利不这么认为，他从小就看着画家母亲每天在花街细细地勾勒街道和游人的样子额，他知道能像母亲一样生活是他的理想。为了学会绘画，他年复一年地练习，用自己粗笨的手学习着操控画笔。最终，赛利成为了洛阳最出名的画家！',MoveSpdRate=1,DefaultDialog=452280,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,LoadShowPose={0,-0.2,0},ManualMap=100,NpcWalk=2407,BodyChangeColor=1,DefaultRolePartID=1160,}",
