  [809266] = "{id=809266,NameZh='飞飞',DisablePlayshow=1,ShowName=2,Body=1916,Gender=2,BodyDefaultColor=0,Head=600100,MoveSpdRate=1,DefaultDialog=480247,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,NoShowIcon=1,Features=32,DefaultRolePartID=1157,}",
  [809267] = "{id=809267,NameZh='乐乐',DisablePlayshow=1,ShowName=2,Body=10272,Gender=2,BodyDefaultColor=0,Icon='809267',AdventureSort=432,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='每个来花楼的人，都想见一见花楼最美貌的舞女乐乐。他们说，只要看着乐乐的眼睛，灵魂仿佛就被吸走了一样，再也挪不开。只要乐乐在花楼里走动，总是会有无数双眼睛盯着她的身姿，也有无数个叹息声从各个角落传出来。虽然乐乐得到了世人的垂怜，可是只有她自己才知道自己的真实身份是山野里亦男亦女的狐妖。尽管狐妖能魅惑他人，却也无法得到真正的深爱。狐妖乐乐，一直在等着一个人，能看清自己皮囊下孤独的灵魂。',MoveSpdRate=1,DefaultDialog=480248,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,Features=32,ManualMap=100,DefaultRolePartID=1148,}",
