  [809292] = "{id=809292,NameZh='崔斯坦',ShowName=2,MapIcon='map_games',Body=1906,Gender=1,BodyDefaultColor=0,Hair=1393,Icon='Dragon_M',AdventureSort=440,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='活泼开朗的青年。原先在花楼工作，学会了很多变戏法的本事，自创了不少新奇的小游戏。由于自来熟的脾气，经常会拉上过路人一起玩。',MoveSpdRate=1,DefaultDialog=451951,NpcFunction={{type=3275}},IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=102,BodyChangeColor=2,DefaultRolePartID=1026,}",
