  [809365] = "{id=809365,NameZh='雷藏',DisablePlayshow=1,ShowName=2,Guild='魔法公会',GuildEmblem='icon_2_2',AtlasOpt='career',Body=1118,Gender=1,RightHand=40620,Hair=1105,Head=400147,Icon='NPC_LighttingCast',Desc='来自吉芬城的贵族魔法师，在魔法的海洋中拥有无与伦比的天赋，是有史以来最天才的魔法师之一，为人古板，视吉芬与魔法公会为一切，如今已经是城中有数的强者，镇守在吉芬城。',MoveSpdRate=1,DefaultDialog=651490,IsVeer=1,move=0,AccessRange=2,Emoji=12,Action=9,Purikura='Raizan',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1046,}",
  [809366] = "{id=809366,NameZh='无名者',DisablePlayshow=1,ShowName=2,Guild='刺客公会',GuildEmblem='icon_3_2',AtlasOpt='career',Position='首领',Body=1119,Gender=1,BodyDefaultColor=0,LeftHand=140902,RightHand=140902,Hair=1104,Head=400148,VisitVocal='Npc/Cutmounk_1-Npc/Cutmounk_5',EndVocal='Npc/Cutmounk_2-Npc/Cutmounk_4-Npc/Cutmounk_6',Icon='NPC_Cutmounk',Desc='从刺客公会秘境中走出的强者，曾经于古城成功刺杀鹗枭男爵而闻名于世，作为刺客，他谨遵刺客守则，为人极度冷静，不苟言笑，视刺客公会的使命为生命，是刺客公会的会长。',MoveSpdRate=1,DefaultDialog=651491,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,Purikura='Noone',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1041,}",
