  [809379] = "{id=809379,NameZh='卡巴克',DisablePlayshow=1,ShowName=2,GuildEmblem='icon_4_2',AtlasOpt='career',Position='白银微风',Body=29,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45089,VisitVocal='Npc/Kabake_1-Npc/Kabake_2',Desc='穿着东方风的贵族气质男子，喜欢在下午优雅地喝着红茶。高高在上的皇家气质和某种说不出的奇怪气场让人觉得和其谈话压力甚大…（日语CV：杉山紀彰）',MoveSpdRate=1,DefaultDialog=651504,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,DefaultRolePartID=1012,}",
  [809380] = "{id=809380,NameZh='伊丝米儿',DisablePlayshow=1,ShowName=2,GuildEmblem='icon_3_2',AtlasOpt='career',Position='暗影之手',Body=22,Eye=2,Gender=2,BodyDefaultColor=0,Hair=13,Head=45013,VisitVocal='Npc/Yisimier_1-Npc/Yisimier_2-Npc/Yisimier_3',Desc='将自己隐藏在黑暗中的女子，感觉不到一丝气息存在，是个背负着各种不祥传说的人。沉默寡言，等对方感觉到其杀气的时候已经离死亡不远了。（日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=651505,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,DefaultRolePartID=1114,}",
  [809381] = "{id=809381,NameZh='休朗克',DisablePlayshow=1,ShowName=2,GuildEmblem='icon_1_2',AtlasOpt='career',Position='王国之盾',Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,VisitVocal='Npc/Xiulangke_2',EndVocal='Npc/Xiulangke_1-Npc/Xiulangke_3',Desc='一个豪迈的络腮胡大叔，健硕的肌肉上有着无数的伤痕和刀疤，仿佛在向冒险者倾诉他曾经的那些辉煌战果…（日语CV：石田彰）',MoveSpdRate=1,DefaultDialog=651506,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,DefaultRolePartID=1026,}",
  [809382] = "{id=809382,NameZh='莱伊娜丝',DisablePlayshow=1,ShowName=2,GuildEmblem='icon_5_2',AtlasOpt='career',Position='圣诗之歌',Body=40,Eye=2,Gender=2,BodyDefaultColor=0,Hair=14,Head=45081,VisitVocal='Npc/Laiyinasi_1-Npc/Laiyinasi_2-Npc/Laiyinasi_3',Desc='一位令人敬重的修女，从其身上能感受到圣母般的慈爱。对所有人都非常关爱，尤其对想转职为服事系的冒险者，会给予极大的帮助和指导。（日语CV：大谷育江）',MoveSpdRate=1,DefaultDialog=651507,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultRolePartID=1108,}",
