  [809523] = "{id=809523,NameZh='五郎',ShowName=2,Position='极速美味',Body=1138,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat1',Desc='天生活泼好动的五郎，也选择了最适合自己性格的职业，外卖猫！成为了外卖猫的五郎是最受欢迎的佣兵之一，对雇主悉心照顾，他不会允许自己的雇主受伤！',MoveSpdRate=1,DefaultDialog=82150,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,DefaultRolePartID=1167,}",
  [809524] = "{id=809524,NameZh='阿宝',ShowName=2,Position='稳重如山',Body=1139,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat2',Desc='以一身厉害的功夫武道闻名，神秘的猫猫佣兵团成员！阿宝是以武力著称的佣兵，深得雇主们的信任，因为有阿宝在，他们的安危就不会受到威胁！',MoveSpdRate=1,DefaultDialog=82990,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,DefaultRolePartID=1161,}",
  [809525] = "{id=809525,NameZh='美莎',ShowName=2,Position='优雅之樱',Body=1140,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat3',Desc='优雅的舞步，高傲神秘的猫猫佣兵团成员！美莎是以魔法攻击著称的佣兵猫，一切在危险在美莎的魔法下都不堪一击，敌人们沉迷于美莎的舞姿，倒在了美莎的魔法之下。雇主们很乐意雇佣美莎这个多才多艺的佣兵猫。',MoveSpdRate=1,DefaultDialog=84632,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,DefaultRolePartID=1163,}",
  [809526] = "{id=809526,NameZh='山葵',ShowName=2,Position='狂风怒涛',Body=1141,Gender=3,BodyDefaultColor=0,Hair=0,Icon='SoldierCat4',Desc='以佣兵团的盾牌自称，神秘的猫猫佣兵团成员！山葵是以坚固的防御闻名于世的佣兵，在关键时刻敢于为雇主抵挡致命一击，深得雇主们的信任，有山葵在，雇主们从来不担心自己的生命是否收到威胁！',MoveSpdRate=1,DefaultDialog=84482,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,NormalDisplay=1,DefaultRolePartID=1166,}",
