  [809719] = "{id=809719,NameZh='彩妮',DisablePlayshow=1,ShowName=2,Body=1916,Gender=2,BodyDefaultColor=0,Hair=16,HeadDefaultColor=1,Icon='809719',AdventureSort=434,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='银鱼湖底的原住民有很多，其中鱼怪是最受歧视的。因为他们看上去很笨拙，又没什么魔法天赋，跟美丽的红尾人鱼比起来，实在是不起眼。彩妮忍受不了其他生物的白眼，开始学习变形法术，希望自己能变成其他的种族。终于，她学会变成蝴蝶精灵，当她离开阴冷的湖底，在阳光下煽动自己五彩的翅膀时，她觉得一切都是值得的，她发誓自己将脱离鱼怪的身份永远作为蝴蝶精灵活在洛阳。直到有一天，她看见其他的鱼怪被欺负，为了帮助自己的同胞，她变回鱼怪，并且将变身的奥秘一点点教会给自己的同胞，帮助鱼怪们用别的身份在洛阳活下去。',MoveSpdRate=1,DefaultDialog=480317,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,ManualMap=101,DefaultRolePartID=1154,}",
