  [809987] = "{id=809987,NameZh='艾露',DisablePlayshow=1,ShowName=2,Position='祭祀长',Body=1909,Gender=2,Head=49221,Icon='811170',AdventureSort=438,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='荒境的祭祀长，负责对神树平时的供奉与祈祷。面容美丽，被誉为毒牙族之花。不爱说话，但是心思细腻，善解人意。',MoveSpdRate=1,DefaultDialog=452085,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=102,DefaultRolePartID=1099,}",
