  [810081] = "{id=810081,NameZh='音乐盒',DisableWait=1,DisablePlayshow=1,ShowName=1,Shape='L',Body=1083,Gender=4,BodyDefaultColor=0,VisitVocal='Npc/MusicBox_1-Npc/MusicBox_2-Npc/MusicBox_3-Npc/MusicBox_4',EndVocal='Npc/MusicBox_5-Npc/MusicBox_6-Npc/MusicBox_7-Npc/MusicBox_8',Icon='musicbox',Desc='A.W  1010年，卡普拉公司为了庆祝会社成立百年，引进了里希塔乐的科学技术和自己对魔导晶体回路的研究，而研制成的。目前编号：KP-01（日语CV：大谷育江）',MoveSpdRate=1,DefaultDialog=53175,IsVeer=0,move=0,AccessRange=2,Emoji=26,Action=9,Scale=2,ShadowCastOff=1,DefaultRolePartID=1170,}",
  [810082] = "{id=810082,NameZh='弗雷德',ShowName=2,Position='惊奇玩具',Body=1098,Gender=1,RightHand=400088,Hair=4,Head=400089,Icon='2158',Desc='古灵精怪的小鬼，父亲是鼎鼎大名的发明家和收藏家皮耶罗，从小就被父亲影响的他也喜欢捣鼓各种神奇的小玩意儿，在首都的孩子群中很有人气。是节日派对的道具达人！',MoveSpdRate=1,DefaultDialog=131483,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,DefaultRolePartID=1041,}",
