  [810310] = "{id=810310,NameZh='菲利',DisablePlayshow=1,ShowName=2,Body=2135,Gender=1,Hair=1429,Icon='Fili',AdventureSort=455,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='爽朗过头的精灵男子，其魔力与四周微妙地格格不入。据说是圣女赫蒂的兄长，但并没有任何证据证明两人有亲缘关系。甚至连菲利的诞生，都好像是在众精灵的记忆中凭空出现的……',MoveSpdRate=1.3,DefaultDialog=710819,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.1,LoadShowSize=0.8,Features=32,ManualMap=120,DefaultRolePartID=1015,}",
  [810311] = "{id=810311,NameZh='贞奴比亚',DisablePlayshow=1,ShowName=2,Body=2117,Gender=2,Icon='Priest',AdventureSort=456,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='辉煌领域的现任大祭司，芙蕾雅女神的神使之一。雷厉风行、冷冽优雅的大魔法使。为了让彩虹桥恢复原状，在蔚云之海创造了修复法阵。',MoveSpdRate=1.3,DefaultDialog=710820,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=109,Purikura='Priest',DefaultRolePartID=1107,}",
