  [811286] = "{id=811286,NameZh='古恩',ShowName=2,Body=1776,Gender=3,Desc='传说中，远古的巨人伊米儿有一颗慈悲的心，他时常躲在虚空中注视着九大世界的运转，帮助各个种族繁荣生长。他经常久久地凝望洛阳和他亲手创造的法纳族，其中最出色的人就是古恩。古恩有着不逊于战神的远古巨龙之力，不输于伊米儿的慈悲之心。千年前，他为了保护洛阳，牺牲自己的身体和自由，化身巨龙，斩断时空的连接，让洛阳脱离九大世界的时空。现如今，他依然用自己庞大的龙身缠绕着洛阳的流之云边，在高山之上遥望洛阳城的居民。',MoveSpdRate=1,DefaultDialog=603587,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1161,}",
  [811287] = "{id=811287,NameZh='索杰',ShowName=2,Position='龙族战士',Body=933,Eye=1,Gender=1,Hair=1,HeadDefaultColor=3,Head=49192,AdventureSort=426,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='只要有架可以打，索杰就非常快乐！身为龙神拳法的传承人，索杰毕生的追求就是找到所有武艺比自己强的对手，然后一一打败他们！在一众洛阳的锦衣卫里，索杰挑中了最年轻最有潜力的锦衣卫平安作为自己培养目标，他经常指点平安的武艺，力求把平安变成洛阳最强的武艺大师，与自己切磋武学，走向更深奥的领域。',MoveSpdRate=1.4,DefaultDialog=551347,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,NoShowIcon=1,Scale=1.1,ManualMap=99,DefaultRolePartID=1076,}",
