  [811298] = "{id=811298,NameZh='艾莫罗',DisablePlayshow=1,ShowName=0,Position='流浪者',Body=1106,Gender=1,BodyDefaultColor=0,Hair=63,HeadDefaultColor=4,Head=45142,Tail=48007,MoveSpdRate=1,DefaultDialog=481342,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,NpcWalk=2831,DefaultRolePartID=1064,}",
  [811299] = "{id=811299,NameZh='艾里拉',DisablePlayshow=1,ShowName=2,Position='锦衣卫',Body=1904,Gender=1,BodyDefaultColor=0,HeadDefaultColor=4,Icon='Trooper_M',AdventureSort=433,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='小时候的艾里拉是一个叛逆的孩子，他整天在街道上游荡，做些偷鸡摸狗的活。有天，他偷东西的时候，正好碰见乔装的许仙，许仙抓住艾里拉，拉着他走向影枫司。艾里拉觉得，自己可能会被影枫司的锦衣卫狠狠地教训。没想到许仙将他推荐给法海，称赞他头脑机灵，手脚动作敏捷。影枫司收留了艾里拉，悉心照料他，将他养大成人，培养成出色的锦衣卫。艾里拉成为锦衣卫里最熟悉洛阳罪犯，破案能力最强的一员，用他的经历保护洛阳的安全。',MoveSpdRate=1.3,DefaultDialog=481343,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=101,DefaultRolePartID=1038,}",
