  [811366] = "{id=811366,NameZh='安布罗斯的声音',DisableWait=1,DisablePlayshow=1,ShowName=2,Position='月之守护者',Body=3,Eye=1,Gender=1,BodyDefaultColor=0,RightHand=40340,Hair=2,HeadDefaultColor=6,MoveSpdRate=1,DefaultDialog=651158,IsVeer=1,move=0,AccessRange=2,Emoji=22,Action=9,NoShowIcon=1,DefaultRolePartID=1006,}",
  [811367] = "{id=811367,NameZh='塔米的声音',ShowName=2,Position='日之守护者',Body=4,Eye=2,Gender=1,BodyDefaultColor=0,RightHand=40344,Hair=15,HeadDefaultColor=7,MoveSpdRate=1,DefaultDialog=651142,IsVeer=1,move=0,AccessRange=2,Emoji=22,Action=9,NoShowIcon=1,DefaultRolePartID=1024,}",
  [811368] = "{id=811368,NameZh='许仙',DisablePlayshow=1,ShowName=2,Position='洛阳城主',Body=1898,Gender=1,Icon='XuXian',Desc='洛阳城主许仙，一个出身在银鱼湖底，神圣之花中的男人。在许仙出生的那天，法海抱着他出现在洛阳所有居民前，就向所有人宣布怀中的孩子会成为洛阳的主人。他在平静又繁荣的洛阳城度过了500年的快乐生活，没有辜负大家的希望，成为一个负责任的城主，虽然有时候会有些调皮。',MoveSpdRate=1,DefaultDialog=652449,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.1,Features=32,Purikura='XuXian_umbrella',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1049,}",
  [811369] = "{id=811369,NameZh='白素贞',DisablePlayshow=1,ShowName=2,Body=1900,Gender=2,Icon='BaiSuzhen',Desc='花容月貌和神秘的身世让白素贞成为一个复杂的女人，只有在脆弱的时刻，她才会对亲近信赖的人透露自己内心的秘密。灯火大会与许仙的相遇，成功突破她内心的防线，让她被冰冻的内心开始动摇，爱情的嫩芽开始从她的心底长了出来。她不希望自己的感情影响自己的计划，却又无克制地想要靠近许仙…',MoveSpdRate=1,DefaultDialog=652450,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.1,Features=32,Purikura='BaiSuzhen',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1127,}",
  [811370] = "{id=811370,NameZh='法海',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫指挥使',Body=1903,Gender=1,Icon='FaHai',Desc='法海是洛阳城法纳族的领袖，也是洛阳安保机构影枫司的领导者。他性格沉静，头脑睿智，是全洛阳人心目中的英雄。法海的父亲是龙神古恩的好友裴休，母亲的种族是洛阳的迷。有传言说法海的母亲是来自深渊的恶魔，也有传言说，法海有古代神族的血统。这也为法海添加了一丝神秘的气质，这个有着银色长发的法纳族男人也是洛阳女妖心里的梦中情人。',MoveSpdRate=1,DefaultDialog=652451,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.2,Features=32,Purikura='FaHai',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1013,}",
  [811371] = "{id=811371,NameZh='平安',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='锦衣卫',Body=1904,Gender=1,Icon='Trooper_M',Desc='影枫司最年轻的锦衣卫，有人说平安就像年轻的法海一样，充满朝气和希望。平安也是这样对自己说的，他会成为继古恩法海之后，洛阳下一代守护者！为了达成这个目标，平安日夜修炼自己的魔法和武艺，最终成为法海身边最得力的助手。平安还有着一颗善良的心，经常无私的帮助身边的人。洛阳城的居民都很喜欢这个年轻又出色的法纳族！',MoveSpdRate=1,DefaultDialog=652452,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Purikura='Trooper_M',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1072,}",
  [811372] = "{id=811372,NameZh='小绿',DisablePlayshow=1,ShowName=2,Guild='影枫司',Position='医疗师',Body=1907,Gender=2,Hair=51,HeadDefaultColor=1,MoveSpdRate=1,DefaultDialog=652453,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Features=32,DefaultRolePartID=1134,}",
  [811373] = "{id=811373,NameZh='小青',DisablePlayshow=1,ShowName=2,Position='花楼老板',Body=1902,Gender=2,Icon='XiaoQing',Desc='出身于花楼之中，毒牙少女小青从小就见惯了男女之间的爱恨情仇。她的母亲，曾经是名满洛阳的花魁，多少洛阳的富家子弟愿意花无数的财富只为了见上一面！也许，美神也嫉妒小青母亲的美貌，让她年纪轻轻就患病离世。同样是孤儿的白素贞可怜小青，承担了抚养小青的责任，伴随她一路成长。长大的小青继承了母亲的美貌，也摒弃了母亲多愁善感的性格，成为花楼当家的主人。',MoveSpdRate=1,DefaultDialog=652454,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Features=32,DefaultRolePartID=1081,}",
  [811374] = "{id=811374,NameZh='白素贞',DisablePlayshow=1,ShowName=1,Body=1901,Gender=2,Icon='Flower_BaiSuzhen',MoveSpdRate=3,DefaultDialog=652455,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Features=32,DefaultRolePartID=1127,}",
