  [811424] = "{id=811424,NameZh='许仙',DisablePlayshow=1,ShowName=2,Position='洛阳城主',Body=1898,Gender=1,Icon='XuXian',Desc='洛阳城主许仙，一个出身在银鱼湖底，神圣之花中的男人。在许仙出生的那天，法海抱着他出现在洛阳所有居民前，就向所有人宣布怀中的孩子会成为洛阳的主人。他在平静又繁荣的洛阳城度过了500年的快乐生活，没有辜负大家的希望，成为一个负责任的城主，虽然有时候会有些调皮。',MoveSpdRate=1,DefaultDialog=652505,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Scale=1.1,Features=32,Purikura='XuXian_umbrella',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1049,}",
  [811425] = "{id=811425,NameZh='古恩',ShowName=2,Body=1776,Gender=3,Desc='传说中，远古的巨人伊米儿有一颗慈悲的心，他时常躲在虚空中注视着九大世界的运转，帮助各个种族繁荣生长。他经常久久地凝望洛阳和他亲手创造的法纳族，其中最出色的人就是古恩。古恩有着不逊于战神的远古巨龙之力，不输于伊米儿的慈悲之心。千年前，他为了保护洛阳，牺牲自己的身体和自由，化身巨龙，斩断时空的连接，让洛阳脱离九大世界的时空。现如今，他依然用自己庞大的龙身缠绕着洛阳的流之云边，在高山之上遥望洛阳城的居民。',MoveSpdRate=1,DefaultDialog=652506,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1161,}",
