  [811483] = "{id=811483,NameZh='漫特',DisablePlayshow=1,ShowName=2,Position='龙神长老',Body=933,Eye=1,Gender=1,Hair=1,HeadDefaultColor=3,Head=49192,Desc='在洛阳的龙神里，也许漫特不是拳法最高深的那个（毕竟有个打架狂人索杰），但他肯定最乐于助人的一个，也因为他乐于去教导其他龙神孩子拳法，他的徒弟遍布整个洛阳！因此，龙神公会选择漫特作为龙神的长老，希望其他的龙神都能学习漫特的精神。一个龙神是否强大，跟他的拳法有关系，更与他多么愿意为世界奉献有关系。',MoveSpdRate=1,DefaultDialog=652564,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Features=32,DefaultRolePartID=1022,}",
