  [811493] = "{id=811493,NameZh='波赞比莉',DisablePlayshow=1,ShowName=0,Body=63,Eye=2,Gender=2,Hair=13,HeadDefaultColor=5,Head=49193,MoveSpdRate=1,DefaultDialog=652574,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1126,}",
  [811494] = "{id=811494,NameZh='索杰',DisablePlayshow=1,ShowName=2,Position='龙族战士',Body=933,Eye=1,Gender=1,Hair=1,HeadDefaultColor=3,Head=49192,Desc='只要有架可以打，索杰就非常快乐！身为龙神拳法的传承人，索杰毕生的追求就是找到所有武艺比自己强的对手，然后一一打败他们！在一众洛阳的锦衣卫里，索杰挑中了最年轻最有潜力的锦衣卫平安作为自己培养目标，他经常指点平安的武艺，力求把平安变成洛阳最强的武艺大师，与自己切磋武学，走向更深奥的领域。',MoveSpdRate=1.4,DefaultDialog=652575,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.1,DefaultRolePartID=1076,}",
  [811495] = "{id=811495,NameZh='钱娘',ShowName=2,Body=10301,Gender=2,Icon='Miyabi_10',Desc='花楼有个特别的舞女，名字叫做钱娘。据传言说，她原本是洛阳出名的魔法大师，她跟自己的恋人一起建立了一座法师塔，常年在塔里研究魔法的奥秘！因为跟恋人在魔法理念上有些不同，钱娘生气地跑到花楼喝酒消愁，与老板小青相识成为了朋友。在花楼的这段日子，让钱娘明白，身处在高塔研究地魔法永远是理论，只有在群众里生活才能明白魔法真正的奥秘，为了能贴近人群，研究洛阳人真正需要的法术，她长年客居花楼。偶尔，她也会因为心情比较好，为其他客人跳跳舞。大家只知道，花楼有个高傲地舞女钱娘，却不知道这个舞女也是洛阳许多魔法的创造人！',MoveSpdRate=1,DefaultDialog=652576,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1126,}",
  [811496] = "{id=811496,NameZh='娇丽娜',DisablePlayshow=1,ShowName=0,Body=1560,Eye=2,Gender=2,BodyDefaultColor=0,Hair=74,HeadDefaultColor=9,Head=45094,MoveSpdRate=1,DefaultDialog=652577,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1099,}",
