  [811498] = "{id=811498,NameZh='芭丽馥',DisablePlayshow=1,ShowName=0,Body=65,Eye=2,Gender=2,BodyDefaultColor=0,Hair=31,HeadDefaultColor=4,Head=49193,MoveSpdRate=1.7,DefaultDialog=652579,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1112,}",
  [811499] = "{id=811499,NameZh='桃波',DisablePlayshow=1,ShowName=0,Body=1705,Gender=2,BodyDefaultColor=0,Head=49193,MoveSpdRate=1,DefaultDialog=652580,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1133,}",
  [811500] = "{id=811500,NameZh='米诺·特里登',DisablePlayshow=1,ShowName=0,Body=1908,Gender=1,BodyDefaultColor=0,Icon='Serpent_M',MoveSpdRate=1,DefaultDialog=652581,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=0.7,BodyChangeColor=1,DefaultRolePartID=1032,}",
  [811501] = "{id=811501,NameZh='乐乐',DisablePlayshow=1,ShowName=0,Body=10272,Gender=2,BodyDefaultColor=0,Icon='809267',Desc='每个来花楼的人，都想见一见花楼最美貌的舞女乐乐。他们说，只要看着乐乐的眼睛，灵魂仿佛就被吸走了一样，再也挪不开。只要乐乐在花楼里走动，总是会有无数双眼睛盯着她的身姿，也有无数个叹息声从各个角落传出来。虽然乐乐得到了世人的垂怜，可是只有她自己才知道自己的真实身份是山野里亦男亦女的狐妖。尽管狐妖能魅惑他人，却也无法得到真正的深爱。狐妖乐乐，一直在等着一个人，能看清自己皮囊下孤独的灵魂。',MoveSpdRate=1,DefaultDialog=652582,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1148,}",
  [811502] = "{id=811502,NameZh='瑞秋',DisablePlayshow=1,ShowName=0,Body=351,Eye=2,Gender=2,BodyDefaultColor=0,Hair=17,HeadDefaultColor=3,Head=49193,MoveSpdRate=1,DefaultDialog=652583,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1115,}",
  [811503] = "{id=811503,NameZh='罗观',DisablePlayshow=1,ShowName=0,Body=277,Eye=1,Gender=1,BodyDefaultColor=3,Hair=1378,Head=49192,MoveSpdRate=1,DefaultDialog=652584,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1011,}",
