  [811505] = "{id=811505,NameZh='小顽皮',ShowName=2,Body=1918,Gender=2,Hair=1397,MoveSpdRate=1,DefaultDialog=652586,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1148,}",
