  [811507] = "{id=811507,NameZh='鲜花',ShowName=0,Type='GatherNPC',Body=1378,Gender=4,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=652588,IsVeer=0,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Features=524288,ShadowCastOff=1,DefaultRolePartID=1172,}",
  [811508] = "{id=811508,NameZh='平安',DisablePlayshow=1,ShowName=1,Guild='影枫司',Position='锦衣卫',Body=1904,Gender=1,Icon='Trooper_M',Desc='影枫司最年轻的锦衣卫，有人说平安就像年轻的法海一样，充满朝气和希望。平安也是这样对自己说的，他会成为继古恩法海之后，洛阳下一代守护者！为了达成这个目标，平安日夜修炼自己的魔法和武艺，最终成为法海身边最得力的助手。平安还有着一颗善良的心，经常无私的帮助身边的人。洛阳城的居民都很喜欢这个年轻又出色的法纳族！',MoveSpdRate=1.4,DefaultDialog=652589,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,Features=32,Purikura='Trooper_M',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1072,}",
