  [811544] = "{id=811544,NameZh='柔碧特',DisablePlayshow=1,ShowName=0,Body=934,Eye=2,Gender=2,Hair=12,HeadDefaultColor=8,Head=49193,MoveSpdRate=1,DefaultDialog=652625,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1152,}",
  [811545] = "{id=811545,NameZh='波赞比莉',DisablePlayshow=1,ShowName=0,Body=63,Eye=2,Gender=2,Hair=13,HeadDefaultColor=5,Head=49193,MoveSpdRate=1,DefaultDialog=652626,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1126,}",
  [811546] = "{id=811546,NameZh='索杰',DisablePlayshow=1,ShowName=0,Position='龙族战士',Body=933,Eye=1,Gender=1,Hair=1,HeadDefaultColor=3,Head=49192,Desc='只要有架可以打，索杰就非常快乐！身为龙神拳法的传承人，索杰毕生的追求就是找到所有武艺比自己强的对手，然后一一打败他们！在一众洛阳的锦衣卫里，索杰挑中了最年轻最有潜力的锦衣卫平安作为自己培养目标，他经常指点平安的武艺，力求把平安变成洛阳最强的武艺大师，与自己切磋武学，走向更深奥的领域。',MoveSpdRate=1.4,DefaultDialog=652627,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.1,DefaultRolePartID=1076,}",
  [811547] = "{id=811547,NameZh='钱娘',DisablePlayshow=1,ShowName=0,Body=10301,Gender=2,Icon='Miyabi_10',Desc='花楼有个特别的舞女，名字叫做钱娘。据传言说，她原本是洛阳出名的魔法大师，她跟自己的恋人一起建立了一座法师塔，常年在塔里研究魔法的奥秘！因为跟恋人在魔法理念上有些不同，前娘生气地跑到花楼喝酒消愁，与老板小青相识成为了朋友。在花楼的这段日子，让钱娘明白，身处在高塔研究地魔法永远是理论，只有在群众里生活才能明白魔法真正的奥秘，为了能贴近人群，研究洛阳人真正需要的法术，她长年客居花楼。偶尔，她也会因为心情比较好，为其他客人跳跳舞。大家只知道，花楼有个高傲地舞女钱娘，却不知道这个舞女也是洛阳许多魔法的创造人！',MoveSpdRate=1,DefaultDialog=652628,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1126,}",
  [811548] = "{id=811548,NameZh='娇丽娜',DisablePlayshow=1,ShowName=0,Body=1560,Eye=2,Gender=2,BodyDefaultColor=0,Hair=74,HeadDefaultColor=9,Head=45094,MoveSpdRate=1,DefaultDialog=652629,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1099,}",
  [811549] = "{id=811549,NameZh='科亚',DisablePlayshow=1,ShowName=0,Body=664,Eye=1,Gender=1,BodyDefaultColor=0,Hair=1363,Head=49192,MoveSpdRate=1,DefaultDialog=652630,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1008,}",
  [811550] = "{id=811550,NameZh='芭丽馥',DisablePlayshow=1,ShowName=0,Body=65,Eye=2,Gender=2,BodyDefaultColor=0,Hair=31,HeadDefaultColor=4,Head=49193,MoveSpdRate=1.7,DefaultDialog=652631,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1112,}",
  [811551] = "{id=811551,NameZh='桃波',DisablePlayshow=1,ShowName=0,Body=1705,Gender=2,BodyDefaultColor=0,Head=49193,MoveSpdRate=1,DefaultDialog=652632,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1133,}",
  [811552] = "{id=811552,NameZh='米诺·特里登',DisablePlayshow=1,ShowName=0,Body=1908,Gender=1,BodyDefaultColor=0,Icon='Serpent_M',MoveSpdRate=1,DefaultDialog=652633,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=0.7,BodyChangeColor=1,DefaultRolePartID=1032,}",
  [811553] = "{id=811553,NameZh='乐乐',DisablePlayshow=1,ShowName=0,Body=10272,Gender=2,BodyDefaultColor=0,Icon='809267',Desc='每个来花楼的人，都想见一见花楼最美貌的舞女乐乐。他们说，只要看着乐乐的眼睛，灵魂仿佛就被吸走了一样，再也挪不开。只要乐乐在花楼里走动，总是会有无数双眼睛盯着她的身姿，也有无数个叹息声从各个角落传出来。虽然乐乐得到了世人的垂怜，可是只有她自己才知道自己的真实身份是山野里亦男亦女的狐妖。尽管狐妖能魅惑他人，却也无法得到真正的深爱。狐妖乐乐，一直在等着一个人，能看清自己皮囊下孤独的灵魂。',MoveSpdRate=1,DefaultDialog=652634,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1148,}",
  [811554] = "{id=811554,NameZh='瑞秋',DisablePlayshow=1,ShowName=0,Body=351,Eye=2,Gender=2,BodyDefaultColor=0,Hair=17,HeadDefaultColor=3,Head=49193,MoveSpdRate=1,DefaultDialog=652635,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1115,}",
  [811555] = "{id=811555,NameZh='罗观',DisablePlayshow=1,ShowName=0,Body=277,Eye=1,Gender=1,BodyDefaultColor=3,Hair=1378,Head=49192,MoveSpdRate=1,DefaultDialog=652636,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1011,}",
  [811556] = "{id=811556,NameZh='小青',DisablePlayshow=1,ShowName=0,Position='花楼老板',Body=1902,Gender=2,Icon='XiaoQing',Desc='出身于花楼之中，毒牙少女小青从小就见惯了男女之间的爱恨情仇。她的母亲，曾经是名满洛阳的花魁，多少洛阳的富家子弟愿意花无数的财富只为了见上一面！也许，美神也嫉妒小青母亲的美貌，让她年纪轻轻就患病离世。同样是孤儿的白素贞可怜小青，承担了抚养小青的责任，伴随她一路成长。长大的小青继承了母亲的美貌，也摒弃了母亲多愁善感的性格，成为花楼当家的主人。',MoveSpdRate=1,DefaultDialog=652637,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Features=32,DefaultRolePartID=1081,}",
  [811557] = "{id=811557,NameZh='薇安',DisablePlayshow=1,ShowName=0,Position='湖鬼',Body=30088,Gender=1,Icon='cardhead_20037',Desc='薇安是现任银鱼湖主人的小妹妹，也是整个湖底精怪们都喜欢的小公主。她一直自由自在的生活在湖底，没有任何烦恼和忧愁。直到有一天，小人鱼带着薇安去洛阳灯会凑热闹，那天她在靠近水草的角落，看见了让自己一生发生改变的人—法海。从此银鱼湖少了一位小公主，影枫司旁边多了个经常恶作剧的小妖怪。',MoveSpdRate=1,DefaultDialog=652638,IsVeer=1,move=0,AccessRange=2,Emoji=22,Action=9,DefaultRolePartID=1018,}",
  [811558] = "{id=811558,NameZh='莲花灯',DisablePlayshow=1,ShowName=1,Body=1914,Gender=2,MoveSpdRate=1,DefaultDialog=652639,IsVeer=0,move=1,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Features=32,DefaultRolePartID=1139,}",
