  [811829] = "{id=811829,NameZh='耶梦加得',DisablePlayshow=1,ShowName=2,Body=1238,Gender=3,Icon='MagicSnake',MoveSpdRate=1,DefaultDialog=653280,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Scale=2.5,Purikura='Jormungand_SR',PurikuraBG='Adventure_bg_NPC2',DefaultRolePartID=1166,}",
  [811830] = "{id=811830,NameZh='芬里尔',DisablePlayshow=1,ShowName=2,Body=2109,Gender=1,Icon='Fenrir_human',AdventureSort=442,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='耶梦加得与海拉的哥哥，神族与巨人族混血，拥有强大而不同于神族的力量，由于原身为一匹通体白毛的巨狼，被称为“魔狼”。由于命运女神的预言被诸神忌惮，他们将芬里尔三兄妹分别关押，但在诸神黄昏结束时，芬里尔依旧如预言中所说的，将神王奥丁吞噬。诸神因为恐惧，选择将芬里尔关押在月亮上的奥丁神殿之中，并用神器格莱普尼尔囚禁他，永久地剥夺了他的自由。',MoveSpdRate=1.3,DefaultDialog=653281,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,Hide=1,Scale=1.6,LoadShowSize=0.9,ManualMap=107,DefaultRolePartID=1005,}",
