  [811887] = "{id=811887,NameZh='莉迪亚',ShowName=2,Body=2,Eye=46632,Gender=2,Hair=57,HeadDefaultColor=6,MoveSpdRate=1,DefaultDialog=653641,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1114,}",
  [811888] = "{id=811888,NameZh='希格德莉法',ShowName=2,Position='接引人',Body=51591,Eye=2,Gender=2,RightHand=40628,Hair=1693,VisitVocal='Npc/Sigrdrifa_02',Icon='811888',AdventureSort=80,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='克里图拉学院的接引人，负责指导新生入学和成长。同时也是站在学院武力值顶峰的女人，光靠名字就能吓跑魔物。通常情况下很好说话，除非你询问她的年纪。',MoveSpdRate=1,DefaultDialog=653642,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ManualMap=113,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1120,}",
  [811889] = "{id=811889,NameZh='伊莱·雪耳',ShowName=2,Position='博士',Body=60011,Eye=3,Gender=1,Hair=92,VisitVocal='Npc/Eli_01',Icon='811889',AdventureSort=87,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='来自罗扎纳的多兰族学者，热衷于对植物和魔物的学术研究。因为可爱的样貌和温和的态度，多年占据“最受欢迎导师”榜首。平生最大的烦恼，是如何让学生的注意力从自己的尾巴耳朵，转移到研究对象上。',MoveSpdRate=1,DefaultDialog=653643,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,ManualMap=114,ModelRotate=330,ModelSize=1.3,ModelPose={0.04,-0.34,-0.01},DefaultRolePartID=1055,}",
  [811890] = "{id=811890,NameZh='愤怒的曼陀罗',ShowName=2,Body=2173,Gender=4,MoveSpdRate=1,DefaultDialog=653644,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.5,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1172,}",
  [811891] = "{id=811891,NameZh='学院曼陀罗',ShowName=2,Body=2173,Gender=4,MoveSpdRate=1,DefaultDialog=653645,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,Scale=1.5,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1170,}",
  [811892] = "{id=811892,NameZh='阿历克塞',ShowName=2,Position='新人教官',Body=885,Eye=1,Gender=1,RightHand=40717,Hair=41,HeadDefaultColor=4,VisitVocal='Npc/Aleksey_01',AdventureSort=88,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='令新老学生闻之色变的魔鬼教官，最大的爱好就是把学生往死里操练。平素豪放不羁，但夜深人静时，偶尔会对着学院中的一副画像低语。“阿历克西亚，如果我们的老师当初能再负责一些，你是不是就能……算了，都过去了。”',MoveSpdRate=1,DefaultDialog=653646,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=114,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1044,}",
