  [811912] = "{id=811912,NameZh='微笑小姐',ShowName=2,Guild='乐园团',GuildEmblem='guild_03',MapIcon='map_smile',AtlasOpt='guild',Position='接待员',Body=1087,Gender=2,Hair=1087,VisitVocal='Npc/NPC10',EndVocal='Npc/GuiderOfEden_3-Npc/GuiderOfEden_5',Icon='MissSmile',Desc='使人又爱又恨的微笑小姐·安妮，上一刻在天堂下一秒就能让你下地狱，想说爱你不容易。（日语CV：笠原あきら）',MoveSpdRate=1,DefaultDialog=653710,NpcFunction={{name='头饰制作',type=304}},FnIcon='66',FnDesc='头饰制作',IsVeer=1,move=0,AccessRange=2,Emoji=20,Action=9,Hide=1,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [811913] = "{id=811913,NameZh='维托和希达',DisablePlayshow=1,ShowName=2,Body=653,Eye=2,Gender=2,Hair=1679,Head=45001,MoveSpdRate=1,DefaultDialog=653713,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,DefaultRolePartID=1121,}",
  [811914] = "{id=811914,NameZh='奥尔加',ShowName=2,Position='学院小精灵',Body=2193,Gender=1,VisitVocal='Npc/Mail_1-Npc/Mail_2-Npc/Mail_3',EndVocal='Npc/Mail_1-Npc/Mail_2-Npc/Mail_3',Icon='SortingHat',AdventureSort=85,AdventureValue=20,AdventureReward={item={{110,5}}},Condition=5,Desc='超长待机以至于年龄不可考的学院小精灵，据说是“改革者”克里图拉校长创造的魔法生物。尽管有着熊孩子般喜怒无常的脾气，但它绝对是最热爱学院的教员之一。“咕咕，奥尔加会一直留在这里，陪着学院、陪着你。”',MoveSpdRate=1,DefaultDialog=653942,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,NoShowIcon=1,LoadShowPose={0,0,-0.3},ManualMap=113,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1047,}",
