  [811952] = "{id=811952,NameZh='人形测试',ShowName=2,Body=51591,Eye=2,Gender=2,RightHand=40628,Hair=1693,Icon='811888',Desc='伪装成人类混迹于学院的女武神，肩负着守护学院、培养冒险者的任务。如今受到命运女神的关照，担任“命运之风”的接引人。通常情况下很好说话，除非你询问她的年纪。',MoveSpdRate=1,DefaultDialog=654534,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1117,}",
  [811953] = "{id=811953,NameZh='猫型测试',ShowName=2,Body=913,Eye=3,Gender=1,Hair=92,Head=3001162,Icon='811889',Desc='来自罗扎纳的多兰族学者，热衷于对植物和魔物的学术研究。因为可爱的样貌和温和的态度，多年占据“最受欢迎导师”榜首。平生最大的烦恼，是如何让学生的注意力从自己的尾巴耳朵，转移到研究对象上。',MoveSpdRate=1,DefaultDialog=654535,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,DefaultRolePartID=1048,}",
