  [812770] = "{id=812770,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1014,Gender=1,BodyDefaultColor=0,Hair=1014,VisitVocal='Npc/Equipmaster_1-Npc/Equipmaster_2',Icon='Equipmaster2',Desc='传说中最强铁匠的徒弟，对自己锻造的东西非常负责，当然有时也会失败…（日语CV：井上和彦）',MoveSpdRate=1,DefaultDialog=656344,IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,Purikura='Ironwork',PurikuraBG='Adventure_bg_NPC2',DefaultDialog_class1=401255,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812771] = "{id=812771,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=51,Head=145078,Icon='Capra_1015',Desc='卡普拉提供了传送、存储、仓库、通信……等等一切你想要的功能，相信我，你根本离不开她ԅ(¯ㅂ¯ԅ) ',MoveSpdRate=1,DefaultDialog=656345,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,Purikura='Capra-_-red',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812772] = "{id=812772,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=51,HeadDefaultColor=7,Head=45078,VisitVocal='Npc/Barber_1-Npc/Barber_3-Npc/Barber_4',EndVocal='Npc/Barber_2-Npc/Barber_5',Icon='NPC_Capra',Desc='大美女西莉雅的美发技术在大陆首屈一指，最近理发店新提供了染发服务，想变漂亮就从头开始吧(◕‿◕✿) （日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=656346,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812773] = "{id=812773,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1024,Gender=1,BodyDefaultColor=0,Hair=1024,Head=45056,VisitVocal='Npc/Leader_2-Npc/Leader_3',EndVocal='Npc/Leader_1-Npc/Leader_4',Icon='Leader',Desc='希盖曾经参加过数场王国保卫战，直到膝盖中了一箭，受过重伤的他从此担任转职所的高级导师，指导新人完成转职。（日语CV：井上和彦）',MoveSpdRate=1,DefaultDialog=656347,IsVeer=1,move=0,AccessRange=2,Emoji=24,Action=9,Purikura='Higeiz',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812774] = "{id=812774,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1002,HeadDefaultColor=7,Head=45006,VisitVocal='Npc/CommonStoreFemaleY_1-Npc/CommonStoreFemaleY_2-Npc/CommonStoreFemaleY_3-Npc/CommonStoreFemaleY_4',Icon='1046',Desc='出售道具的邻家女孩，总是认真对待每一位光顾的客人。',MoveSpdRate=1,DefaultDialog=656348,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812775] = "{id=812775,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1002,VisitVocal='Npc/CommonStoreFemaleM_1-Npc/CommonStoreFemaleM_2-Npc/CommonStoreFemaleM_3-Npc/CommonStoreFemaleM_4',Icon='1047',Desc='与乔亚是一对姐妹花，传说买过她们所有出售的装备，将会以身相许！Ｏ(≧∇≦)Ｏ',MoveSpdRate=1,DefaultDialog=656349,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultDialog_class1=401256,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812776] = "{id=812776,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1015,VisitVocal='Npc/CommonStoreFemaleM_1-Npc/CommonStoreFemaleM_2-Npc/CommonStoreFemaleM_3-Npc/CommonStoreFemaleM_4',Icon='1075',Desc='与奥拉是一对姐妹花，传说买过她们所有出售的装备，将会以身相许！Ｏ(≧∇≦)Ｏ',MoveSpdRate=1,DefaultDialog=656350,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultDialog_class1=401257,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812777] = "{id=812777,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1093,Gender=2,VisitVocal='Npc/GuiderOfEden_1-Npc/GuiderOfEden_2-Npc/GuiderOfEden_4',EndVocal='Npc/GuiderOfEden_3-Npc/GuiderOfEden_5',Icon='MissSmile',Desc='使人又爱又恨的微笑小姐·安妮，上一刻在天堂下一秒就能让你下地狱，想说爱你不容易。（日语CV：笠原あきら）',MoveSpdRate=1,DefaultDialog=656351,IsVeer=1,move=0,AccessRange=2,Emoji=20,Action=9,Purikura='Missmile',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812778] = "{id=812778,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,VisitVocal='Npc/Xiulangke_2',EndVocal='Npc/Xiulangke_1-Npc/Xiulangke_3',Desc='一个豪迈的络腮胡大叔，健硕的肌肉上有着无数的伤痕和刀疤，仿佛在向冒险者倾诉他曾经的那些辉煌战果…（日语CV：石田彰）',MoveSpdRate=1,DefaultDialog=656352,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812779] = "{id=812779,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=22,Eye=2,Gender=2,BodyDefaultColor=0,Hair=13,Head=45013,VisitVocal='Npc/Yisimier_1-Npc/Yisimier_2-Npc/Yisimier_3',Desc='将自己隐藏在黑暗中的女子，感觉不到一丝气息存在，是个背负着各种不祥传说的人。沉默寡言，等对方感觉到其杀气的时候已经离死亡不远了。（日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=656353,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812780] = "{id=812780,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=29,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45089,VisitVocal='Npc/Kabake_1-Npc/Kabake_2',Desc='穿着东方风的贵族气质男子，喜欢在下午优雅地喝着红茶。高高在上的皇家气质和某种说不出的奇怪气场让人觉得和其谈话压力甚大…（日语CV：杉山紀彰）',MoveSpdRate=1,DefaultDialog=656354,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812781] = "{id=812781,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=40,Eye=2,Gender=2,BodyDefaultColor=0,Hair=14,Head=45081,VisitVocal='Npc/Laiyinasi_1-Npc/Laiyinasi_2-Npc/Laiyinasi_3',Desc='一位令人敬重的修女，从其身上能感受到圣母般的慈爱。对所有人都非常关爱，尤其对想转职为服事系的冒险者，会给予极大的帮助和指导。（日语CV：大谷育江）',MoveSpdRate=1,DefaultDialog=656355,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812782] = "{id=812782,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1089,Gender=1,RightHand=400141,Hair=2,Icon='Raynojose',Desc='被称为史上最强炼金术师的雷诺一直在研究着一些不为人知的秘密，他的炼金术早已摆脱了物质层面，他已经可以通过一些手段来影响冒险者肌肉神经记忆，当然等价交换也是炼金术师们严格遵守的规则，如果你想体验这种奇妙的感觉，你需要用一颗非常稀有的“轮回之石”去交换。',MoveSpdRate=1,DefaultDialog=656356,IsVeer=1,move=0,AccessRange=2,Emoji=2,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812783] = "{id=812783,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,Hair=1002,Head=45019,VisitVocal='Npc/CommonStoreFemaleY_1-Npc/CommonStoreFemaleY_2-Npc/CommonStoreFemaleY_3-Npc/CommonStoreFemaleY_4',Icon='NPC_woman',Desc='能在普隆德拉经商的，都是有才华的人，没有突出战斗力那就一定有非凡的经商头脑。',MoveSpdRate=1,DefaultDialog=656357,IsVeer=1,move=0,AccessRange=2,Emoji=25,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812784] = "{id=812784,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1337,Gender=1,BodyDefaultColor=0,VisitVocal='Npc/Healueman_1-Npc/Healueman_2-Npc/Healueman_3',EndVocal='Npc/Healueman_4-Npc/Healueman_5-Npc/Healueman_6',Icon='NPC_Healueman',Desc='闻名大陆的皇家骑士团团长，以刚正不阿，超卓的战绩威震大陆，普隆德拉王国议会的核心成员之一。他一生从无败绩，对王国忠心耿耿，是普隆德拉的精神支柱之一。（日语CV：鳴海崇志）',MoveSpdRate=1,DefaultDialog=656358,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,Purikura='Hai Luman',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812785] = "{id=812785,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1108,Gender=1,Icon='Teacher',Desc='五彩缤纷的外观并不是梅蒂芬的追求，即使是最普通的颜色梅蒂芬也会加倍用心的调制，最终带给人们绚丽的心情。',DefaultDialog=656359,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812786] = "{id=812786,NameZh='围观群众',ShowName=1,Body=1557,Gender=2,BodyDefaultColor=0,Hair=1370,Icon='House_cleaner2',MoveSpdRate=2,DefaultDialog=310789,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Features=192,DefaultRolePartID=1089,}",
  [812787] = "{id=812787,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1090,Gender=1,VisitVocal='Npc/SkillTeather_1-Npc/SkillTeather_2-Npc/SkillTeather_5',EndVocal='Npc/SkillTeather_3-Npc/SkillTeather_4',Icon='Eden_M_1',Desc='接替在梦罗克牺牲的前辈梅菲尔林瑟成为新的冒险技能导师，虽然不如前辈耐心，但还是尽力将自己会的技能传授给冒险者们，在成为优秀的导师路上努力着。（日语CV：杉山紀彰）',MoveSpdRate=1,DefaultDialog=656361,IsVeer=1,move=0,AccessRange=2,Emoji=20,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812788] = "{id=812788,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1098,Gender=1,RightHand=400088,Hair=4,Head=400089,Icon='2158',Desc='古灵精怪的小鬼，父亲是鼎鼎大名的发明家和收藏家皮耶罗，从小就被父亲影响的他也喜欢捣鼓各种神奇的小玩意儿，在首都的孩子群中很有人气。是节日派对的道具达人！',MoveSpdRate=1,DefaultDialog=656362,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812789] = "{id=812789,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1,Eye=1,Gender=1,BodyDefaultColor=0,RightHand=40302,Hair=2,HeadDefaultColor=4,Desc='天天有着非常广泛的兴趣爱好，直到他在普隆德拉遇到了波利………',MoveSpdRate=1,DefaultDialog=656363,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812790] = "{id=812790,NameZh='围观群众',ShowName=2,Body=1370,Gender=2,BodyDefaultColor=0,Hair=35,HeadDefaultColor=2,MoveSpdRate=1,DefaultDialog=103915,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,DefaultRolePartID=1089,}",
  [812791] = "{id=812791,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=51,Head=145078,Icon='Capra_1015',Desc='卡普拉提供了传送、存储、仓库、通信……等等一切你想要的功能，相信我，你根本离不开她ԅ(¯ㅂ¯ԅ) ',MoveSpdRate=1,DefaultDialog=656365,IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,Purikura='Capra-_-red',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812792] = "{id=812792,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=51,HeadDefaultColor=7,Head=45078,VisitVocal='Npc/Barber_1-Npc/Barber_3-Npc/Barber_4',EndVocal='Npc/Barber_2-Npc/Barber_5',Icon='NPC_Capra',Desc='大美女西莉雅的美发技术在大陆首屈一指，最近理发店新提供了染发服务，想变漂亮就从头开始吧(◕‿◕✿) （日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=656366,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812793] = "{id=812793,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1024,Gender=1,BodyDefaultColor=0,Hair=1024,Head=45056,VisitVocal='Npc/Leader_2-Npc/Leader_3',EndVocal='Npc/Leader_1-Npc/Leader_4',Icon='Leader',Desc='希盖曾经参加过数场王国保卫战，直到膝盖中了一箭，受过重伤的他从此担任转职所的高级导师，指导新人完成转职。（日语CV：井上和彦）',MoveSpdRate=1,DefaultDialog=656367,IsVeer=1,move=0,AccessRange=2,Emoji=24,Action=9,Purikura='Higeiz',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812794] = "{id=812794,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1002,HeadDefaultColor=7,Head=45006,VisitVocal='Npc/CommonStoreFemaleY_1-Npc/CommonStoreFemaleY_2-Npc/CommonStoreFemaleY_3-Npc/CommonStoreFemaleY_4',Icon='1046',Desc='出售道具的邻家女孩，总是认真对待每一位光顾的客人。',MoveSpdRate=1,DefaultDialog=656368,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812795] = "{id=812795,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1002,VisitVocal='Npc/CommonStoreFemaleM_1-Npc/CommonStoreFemaleM_2-Npc/CommonStoreFemaleM_3-Npc/CommonStoreFemaleM_4',Icon='1047',Desc='与乔亚是一对姐妹花，传说买过她们所有出售的装备，将会以身相许！Ｏ(≧∇≦)Ｏ',MoveSpdRate=1,DefaultDialog=656369,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultDialog_class1=401256,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812796] = "{id=812796,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,BodyDefaultColor=0,Hair=1015,VisitVocal='Npc/CommonStoreFemaleM_1-Npc/CommonStoreFemaleM_2-Npc/CommonStoreFemaleM_3-Npc/CommonStoreFemaleM_4',Icon='1075',Desc='与奥拉是一对姐妹花，传说买过她们所有出售的装备，将会以身相许！Ｏ(≧∇≦)Ｏ',MoveSpdRate=1,DefaultDialog=656370,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,DefaultDialog_class1=401257,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812797] = "{id=812797,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1087,Gender=2,Hair=1087,VisitVocal='Npc/GuiderOfEden_1-Npc/GuiderOfEden_2-Npc/GuiderOfEden_4',EndVocal='Npc/GuiderOfEden_3-Npc/GuiderOfEden_5',Icon='MissSmile',Desc='使人又爱又恨的微笑小姐·安妮，上一刻在天堂下一秒就能让你下地狱，想说爱你不容易。（日语CV：笠原あきら）',MoveSpdRate=1,DefaultDialog=656371,IsVeer=1,move=0,AccessRange=2,Emoji=20,Action=9,Purikura='Missmile',PurikuraBG='Adventure_bg_NPC2',ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812798] = "{id=812798,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=7,Eye=1,Gender=1,BodyDefaultColor=0,Hair=2,VisitVocal='Npc/Xiulangke_2',EndVocal='Npc/Xiulangke_1-Npc/Xiulangke_3',Desc='一个豪迈的络腮胡大叔，健硕的肌肉上有着无数的伤痕和刀疤，仿佛在向冒险者倾诉他曾经的那些辉煌战果…（日语CV：石田彰）',MoveSpdRate=1,DefaultDialog=656372,IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812799] = "{id=812799,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=22,Eye=2,Gender=2,BodyDefaultColor=0,Hair=13,Head=45013,VisitVocal='Npc/Yisimier_1-Npc/Yisimier_2-Npc/Yisimier_3',Desc='将自己隐藏在黑暗中的女子，感觉不到一丝气息存在，是个背负着各种不祥传说的人。沉默寡言，等对方感觉到其杀气的时候已经离死亡不远了。（日语CV：喜多村英梨）',MoveSpdRate=1,DefaultDialog=656373,IsVeer=1,move=0,AccessRange=2,Emoji=16,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812800] = "{id=812800,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=29,Eye=1,Gender=1,BodyDefaultColor=0,Hair=5,Head=45089,VisitVocal='Npc/Kabake_1-Npc/Kabake_2',Desc='穿着东方风的贵族气质男子，喜欢在下午优雅地喝着红茶。高高在上的皇家气质和某种说不出的奇怪气场让人觉得和其谈话压力甚大…（日语CV：杉山紀彰）',MoveSpdRate=1,DefaultDialog=656374,IsVeer=1,move=0,AccessRange=2,Emoji=17,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812801] = "{id=812801,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=40,Eye=2,Gender=2,BodyDefaultColor=0,Hair=14,Head=45081,VisitVocal='Npc/Laiyinasi_1-Npc/Laiyinasi_2-Npc/Laiyinasi_3',Desc='一位令人敬重的修女，从其身上能感受到圣母般的慈爱。对所有人都非常关爱，尤其对想转职为服事系的冒险者，会给予极大的帮助和指导。（日语CV：大谷育江）',MoveSpdRate=1,DefaultDialog=656375,IsVeer=1,move=0,AccessRange=2,Emoji=18,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
  [812802] = "{id=812802,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1089,Gender=1,RightHand=400141,Hair=2,Icon='Raynojose',Desc='被称为史上最强炼金术师的雷诺一直在研究着一些不为人知的秘密，他的炼金术早已摆脱了物质层面，他已经可以通过一些手段来影响冒险者肌肉神经记忆，当然等价交换也是炼金术师们严格遵守的规则，如果你想体验这种奇妙的感觉，你需要用一颗非常稀有的“轮回之石”去交换。',MoveSpdRate=1,DefaultDialog=656376,IsVeer=1,move=0,AccessRange=2,Emoji=2,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
  [812803] = "{id=812803,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1002,Gender=2,Hair=1002,Head=45019,VisitVocal='Npc/CommonStoreFemaleY_1-Npc/CommonStoreFemaleY_2-Npc/CommonStoreFemaleY_3-Npc/CommonStoreFemaleY_4',Icon='NPC_woman',Desc='能在普隆德拉经商的，都是有才华的人，没有突出战斗力那就一定有非凡的经商头脑。',MoveSpdRate=1,DefaultDialog=656377,IsVeer=1,move=0,AccessRange=2,Emoji=25,Action=9,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1089,}",
