  [812805] = "{id=812805,NameZh='围观群众',DisablePlayshow=1,ShowName=1,Body=1108,Gender=1,Icon='Teacher',Desc='五彩缤纷的外观并不是梅蒂芬的追求，即使是最普通的颜色梅蒂芬也会加倍用心的调制，最终带给人们绚丽的心情。',DefaultDialog=656379,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1070,}",
