  [812926] = "{id=812926,NameZh='艾伦斯特',DisablePlayshow=1,ShowName=2,Body=2519,Gender=1,BodyDefaultColor=0,Icon='n_musician',AdventureSort=481,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='年轻英俊、技艺高超的宫廷乐师。可他温和的微笑下，却隐藏着些许忧郁和阴翳。“我和王后陛下之间，没有任何僭越的情感。她收养了无父无母的我，而我报以敬爱与感激，仅此而已。”',MoveSpdRate=2,DefaultDialog=656308,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=1001048,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1057,}",
