  [812933] = "{id=812933,NameZh='凯瑟琳',DisablePlayshow=1,ShowName=2,GuildEmblem='qws_family_Kevalbauerig',AtlasOpt='guild',Position='王后',Body=2521,Gender=2,BodyDefaultColor=0,Icon='n_tealqueen',AdventureSort=480,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='凯瑟琳·凯沃宝乐格，卢恩王国的现任王后，出身于海涅家族旁支。与她身份高贵身份齐名的，是她古怪又冷漠的性格。“没有心的王后，丝毫不为失踪的国王担忧。她感兴趣的只有华服与舞会，以及那个年轻漂亮的乐师。”',MoveSpdRate=2,DefaultDialog=656304,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=0,ManualMap=1001048,ModelRotate=335,ModelSize=1.2,ModelPose={0.03,-0.75,0},DefaultRolePartID=1129,}",
