  [813695] = "{id=813695,NameZh='博嘉多',ShowName=2,Body=311,Eye=46622,Gender=2,BodyDefaultColor=0,Hair=35,HeadDefaultColor=4,Head=49193,AdventureSort=513,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='一位身披赤鳞战衣的骑士，总是细心的观察着霞光王座周遭的变化，并细心记录。羽毛笔在羊皮卷上划出火星般的轨迹，琥珀色的竖瞳因创作激情而微微发光。当他注意到你时，慌忙用袖子遮住写满潦草龙语的稿纸，几片赤鳞从抖动的袖口簌簌落下。',MoveSpdRate=1,DefaultDialog=556222,FnIcon='123',FnDesc='霞光王座',IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,LoadShowSize=1,LoadShowPose={0,-0.2,0},ManualMap=154,DefaultRolePartID=1033,}",
