  [817550] = "{id=817550,NameZh='维维塔·坎波',DisablePlayshow=1,ShowName=2,Position='妖精萨满',Body=2141,Gender=1,BodyDefaultColor=0,RightHand=40315,Wing=3002800,Icon='Eclage_Guard',AdventureSort=458,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='现任的小妖精萨满。直爽热情，是密米尔的忠实追随者。原本看布兰迪斯很不顺眼，但在经过一场被对面单方面碾压的比试后，与其成为了好友。',MoveSpdRate=1,DefaultDialog=851840,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Scale=0.7,ManualMap=110,DefaultRolePartID=1064,}",
  [817551] = "{id=817551,NameZh='布兰迪斯',DisablePlayshow=1,ShowName=2,Body=2138,Gender=1,Icon='Hiel',AdventureSort=457,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='外表清冷，内心桀骜不驯的浮空精灵少年。曾经是艾卡拉奇万中无一的天才，但自从兄长卡德去世，他便背弃了原本的族人，立誓要彻底摧毁彩虹桥。',MoveSpdRate=1,DefaultDialog=851841,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=110,Purikura='Hiel',DefaultRolePartID=1004,}",
