  [817680] = "{id=817680,NameZh='赛纳斯',DisablePlayshow=1,ShowName=2,Body=2375,Gender=3,BodyDefaultColor=0,Icon='n_sernas',AdventureSort=461,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='梦幻城第47任贤者，继承了昔日梦幻女王的权杖，并替她守护梦的子民。性格腼腆，有些小书呆子的气质；明明很有能力，却总谦逊到缺乏自信。年幼时曾因为特殊的长相，以为自己是怪物，躲到花丛里哭了三天。后来才知道，自己是非常稀有的幻想种族——皮克西族。',MoveSpdRate=1,DefaultDialog=476725,IsVeer=1,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,LoadShowSize=1.2,ManualMap=128,ModelRotate=330,ModelSize=1.3,ModelPose={0.04,-0.7,-0.01},DefaultRolePartID=1043,}",
