  [817693] = "{id=817693,NameZh='涅拉',DisablePlayshow=1,ShowName=2,Body=2376,Gender=3,BodyDefaultColor=0,Icon='n_nera',AdventureSort=462,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='在克魔岛上备受歧视和排挤的女孩，她苍白的皮肤与其他岛民格格不入，血红的瞳孔以及皮肤上的黑色鳞片，更是她身为“不祥之子”的证明。但事情真的是这样吗？撇去任性和坏脾气，涅拉似乎只是一个充满表现欲、想要当英雄的小孩子。她始终在用自己的火焰，帮助梦幻城抵御魔物的袭击……等等！她的力量又是怎么回事？为什么一个普通的小孩，会有如此凶蛮的幻想之力呢？而那赤红中的黑光，又究竟是什么……',MoveSpdRate=1,DefaultDialog=476724,IsVeer=1,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,LoadShowSize=1.1,ManualMap=128,ModelRotate=330,ModelSize=1.2,ModelPose={0.03,-0.6,0},DefaultRolePartID=1156,}",
