  [821000] = "{id=821000,NameZh='吉赛尔',ShowName=2,MapIcon='map_shop',Position='惊奇玩具商',Body=284,Eye=1,Gender=1,RightHand=400088,Hair=22,Head=45567,Face=3000935,VisitVocal='Npc/NPC07',Icon='821000',Desc='古灵精怪的小鬼，父亲是鼎鼎大名的发明家和收藏家皮耶罗，从小就被父亲影响的他也喜欢捣鼓各种神奇的小玩意儿，在首都的孩子群中很有人气。是节日派对的道具达人！',MoveSpdRate=1,DefaultDialog=361012,NpcFunction={{name='惊奇玩具',param=11,type=600},{type=2100}},FnIcon='65',FnDesc='惊奇玩具',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,Scale=1.2,DefaultRolePartID=1020,}",
  [821001] = "{id=821001,NameZh='B格猫星人',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',MapIcon='map_exchange',AtlasOpt='guild',Position='交易所职员',Body=1102,Gender=1,Hair=1102,Face=400144,VisitVocal='Npc/BigcatMan_1-Npc/BigcatMan_2-Npc/BigcatMan_5-Npc/BigcatMan_6',EndVocal='Npc/BigcatMan_3-Npc/BigcatMan_4-Npc/BigcatMan_7',Icon='BigcatMan',Desc='大陆上最神秘的经贸平台组织，旗下业务范围几乎覆盖整个米德加尔特，甚至连遥远的海外也有其分公司，据爱尔贝塔商业报透露。这帮神秘的黑衣墨镜家伙几乎已经控制了整个大陆的交易和经济…',DefaultDialog=8155,NpcFunction={{type=5000}},FnIcon='icon_60',FnDesc='交易所',IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,Scale=1.2,LoadShowSize=0.9,Purikura='BigCat_Star',PurikuraBG='Adventure_bg_NPC2',DefaultDialog_class1=401258,DefaultRolePartID=1052,}",
