  [822042] = "{id=822042,NameZh='麦琪太太',DisablePlayshow=1,ShowName=2,Position='蜜酿之手',Body=140103,Gender=3,Head=550001,Icon='822042',AdventureSort=469,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='蜂蜜酒馆的老板娘，是幻想乡知名的调酒大师。每一位从幻想之书外来的客人，都该品尝一下她调制鸡尾酒的“醉梦狂想”。“啊啦啦~想知道你的幻想之力长什么样子吗？抿一口我的酒，你就能看见梦的色彩啦！”',MoveSpdRate=1,DefaultDialog=782529,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,Scale=1.2,ManualMap=128,DefaultRolePartID=1184,}",
