  [822049] = "{id=822049,NameZh='鹿鲁特',DisablePlayshow=1,ShowName=2,Position='博闻者',Body=150101,Gender=3,Head=400089,Icon='822049',AdventureSort=470,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='梦幻城著名的游吟诗人，但更喜欢别人称呼他为“博闻者”。年轻时热衷于游历幻想乡的各个角落，直到鹿失前蹄，在一次冒险者折了腿，才不得不安定下来。“呦呦，我说的故事，都是真实发生过的历史！才不是那种，胡编乱造、博人眼球的东西呢！”',MoveSpdRate=1,DefaultDialog=782531,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,Scale=1.2,ManualMap=128,DefaultRolePartID=1179,}",
