  [823737] = "{id=823737,NameZh='汉斯',ShowName=2,MapIcon='map_kapula',Position='远行驿站使者',Body=130001,Gender=2,BodyDefaultColor=0,MoveSpdRate=1,DefaultDialog=782574,NpcFunction={{type=8204},{type=8206},{type=8201},{type=8205},{type=3001}},FnIcon='66',FnDesc='仓库/存储/传送',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,DefaultRolePartID=1122,}",
  [823738] = "{id=823738,NameZh='麦琪太太',DisablePlayshow=1,ShowName=2,Position='蜜酿之手',Body=140103,Gender=3,Head=550001,Icon='822042',Desc='蜂蜜酒馆的老板娘，是幻想乡知名的调酒大师。每一位从幻想之书外来的客人，都该品尝一下她调制鸡尾酒的“醉梦狂想”。“啊啦啦~想知道你的幻想之力长什么样子吗？抿一口我的酒，你就能看见梦的色彩啦！”',MoveSpdRate=1,DefaultDialog=782529,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,Scale=1.2,DefaultRolePartID=1184,}",
  [823739] = "{id=823739,NameZh='饮酒路人1',DisablePlayshow=1,ShowName=1,Body=120004,Gender=3,MoveSpdRate=1,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,NoShowIcon=1,Scale=1.2,Features=32,DefaultRolePartID=1186,}",
  [823740] = "{id=823740,NameZh='饮酒路人2',DisablePlayshow=1,ShowName=1,Body=130002,Gender=3,MoveSpdRate=1,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,NoShowIcon=1,Scale=1.2,Features=32,DefaultRolePartID=1183,}",
  [823741] = "{id=823741,NameZh='鹿鲁特',DisablePlayshow=1,ShowName=2,Position='博闻者',Body=150101,Gender=3,Head=400089,Icon='822049',Desc='梦幻城著名的游吟诗人，但更喜欢别人称呼他为“博闻者”。年轻时热衷于游历幻想乡的各个角落，直到鹿失前蹄，在一次冒险者折了腿，才不得不安定下来。“呦呦，我说的故事，都是真实发生过的历史！才不是那种，胡编乱造、博人眼球的东西呢！”',MoveSpdRate=1,DefaultDialog=782531,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,Scale=1.2,DefaultRolePartID=1179,}",
  [823742] = "{id=823742,NameZh='听众1',DisablePlayshow=1,ShowName=1,Body=160003,Gender=3,MoveSpdRate=1,IsVeer=0,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,NoShowIcon=1,Scale=1.2,DefaultRolePartID=1185,}",
