  [823894] = "{id=823894,NameZh='奇诺',DisablePlayshow=1,ShowName=2,Position='魔法师',Body=15,Eye=46544,Gender=1,Hair=24,HeadDefaultColor=2,AdventureSort=487,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='奇诺是一名海涅家族的魔法师，他同其他的魔法师一样，有了闲工夫就会来到魔法师竞技场跟人比赛，目标是获取竞技场徽章，成为卓越的魔法师。',MoveSpdRate=1,DefaultDialog=483733,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,Hide=1,ManualMap=138,DefaultRolePartID=1081,}",
