  [824166] = "{id=824166,NameZh='玛丽希尔',DisablePlayshow=1,ShowName=2,Body=280,Eye=46645,Gender=2,RightHand=400230,Hair=60,Head=45132,AdventureSort=491,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='玛丽希尔是奈利乌斯家族众多双生子中的一员，她有一位温柔而又为她着想的姐姐，但是为了保护她，姐姐已经离开了人世。玛丽希尔永远不会忘记她的姐姐。',MoveSpdRate=1,DefaultDialog=483828,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=137,Distance=30,DefaultRolePartID=1101,}",
