  [824168] = "{id=824168,NameZh='保罗',DisablePlayshow=1,ShowName=2,Position='卫兵',Body=5,Eye=1,Gender=1,Hair=6,MoveSpdRate=1,DefaultDialog=483820,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,Distance=30,DefaultRolePartID=1069,}",
  [824169] = "{id=824169,NameZh='彼得',DisablePlayshow=1,ShowName=2,Position='卫兵',Body=5,Eye=1,Gender=1,Hair=23,Icon='824169',AdventureSort=490,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='卫兵彼得已经为力哈尔特家族工作多年，看似沉闷的他，其实还有一个鲜为人知的爱好，那就是收集八卦，从他身上能知道许多力哈尔特家族的秘辛哦。',MoveSpdRate=1,DefaultDialog=483822,IsVeer=1,move=0,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=137,Distance=30,DefaultRolePartID=1051,}",
