  [824173] = "{id=824173,NameZh='罗杰·巴尔特',DisablePlayshow=1,ShowName=2,Body=60004,Eye=1,Gender=1,Hair=7,HeadDefaultColor=1,Head=3001830,AdventureSort=492,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='巴尔特家族的罗杰，似乎有着一个与其他巴尔特族人不同的梦想，他非常喜欢看书，特别喜欢看讲传奇海盗故事的书，下次遇到他，试着问他借一本来看看吧。',MoveSpdRate=1,DefaultDialog=483837,IsVeer=1,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=137,Distance=30,DefaultRolePartID=1027,}",
  [824174] = "{id=824174,NameZh='保尔夫·雷根弗莱格',DisablePlayshow=1,ShowName=2,Body=645,Eye=1,Gender=1,Hair=1012,Face=48641,Icon='baoerfu',AdventureSort=493,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='雷根弗莱格家族的保尔夫是一位严格遵守家族规训的年轻人，并且同其他雷根弗莱格家族的人一样，永远不惧他人的挑战。',MoveSpdRate=1,DefaultDialog=483842,IsVeer=1,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=137,Distance=30,DefaultRolePartID=1067,}",
  [824175] = "{id=824175,NameZh='尤尔根·韦格纳',DisablePlayshow=1,ShowName=2,Body=277,Eye=1,Gender=1,Hair=10,HeadDefaultColor=3,AdventureSort=494,AdventureValue=45,AdventureReward={item={{110,5}}},Condition=5,Desc='这位韦格纳家族的传人，似乎有一些自恋？他喜爱到处闲逛，看到美丽地景色，他就会感慨，要是身上带着笔和纸就好了，那他就可以把这美景记录下来。',MoveSpdRate=1,DefaultDialog=483846,IsVeer=1,move=1,AccessRange=2,Emoji=0,Action=9,NoShowIcon=1,ManualMap=137,Distance=30,DefaultRolePartID=1070,}",
