  [826531] = "{id=826531,NameZh='艾莉儿',ShowName=2,MapIcon='map_Alier',Position='音乐精灵',Body=1058,Gender=2,BodyDefaultColor=0,Icon='Arielle',Desc='传说在世界各地使用音乐救死扶伤的精灵，是一位十分美丽的女性，被她救助过的冒险家总是不愿远离她。',MoveSpdRate=1,DefaultDialog=7020,IsVeer=1,move=0,AccessRange=2,Emoji=1,Action=9,DefaultRolePartID=1141,}",
