  [826533] = "{id=826533,NameZh='B格猫星人',DisablePlayshow=1,ShowName=2,GuildEmblem='map_Official-NPC',MapIcon='map_exchange',AtlasOpt='guild',Position='交易所职员',Body=1102,Eye=2,Gender=1,Hair=1102,Face=400144,VisitVocal='Npc/BigcatMan_1-Npc/BigcatMan_2-Npc/BigcatMan_5-Npc/BigcatMan_6',EndVocal='Npc/BigcatMan_3-Npc/BigcatMan_4-Npc/BigcatMan_7',Desc='大陆上最神秘的经贸平台组织，旗下业务范围几乎覆盖整个米德加尔特，甚至连遥远的海外也有其分公司，据爱尔贝塔商业报透露。这帮神秘的黑衣墨镜家伙几乎已经控制了整个大陆的交易和经济…',MoveSpdRate=1,DefaultDialog=485145,NpcFunction={{type=5000}},FnIcon='icon_60',FnDesc='交易所',IsVeer=0,move=0,AccessRange=2,Emoji=14,Action=9,Scale=1.2,LoadShowSize=0.9,Purikura='BigCat_Star',PurikuraBG='Adventure_bg_NPC2',DefaultDialog_class1=401258,DefaultRolePartID=1052,}",
