  [827336] = "{id=827336,NameZh='艾莉儿',ShowName=2,MapIcon='map_Alier',Position='音乐精灵',Body=1058,Gender=2,BodyDefaultColor=0,Icon='Arielle',Desc='传说在世界各地使用音乐救死扶伤的精灵，是一位十分美丽的女性，被她救助过的冒险家总是不愿远离她。',MoveSpdRate=1,DefaultDialog=785337,IsVeer=1,move=0,AccessRange=2,Emoji=1,Action=9,NoShowIcon=1,ShadowCastOff=1,DefaultRolePartID=1141,}",
  [827337] = "{id=827337,NameZh='卡普拉服务人员',ShowName=2,MapIcon='map_kapula',Body=1015,Eye=2,Gender=2,BodyDefaultColor=0,Hair=53,Head=145078,Icon='NPC_Capra',Desc='卡普拉提供了传送、存储、仓库、通信……等等一切你想要的功能，相信我，你根本离不开她ԅ(¯ㅂ¯ԅ) ',MoveSpdRate=1,DefaultDialog=786066,NpcFunction={{type=8204},{type=8206},{type=8201},{type=8205},{type=3001}},FnIcon='66',FnDesc='仓库/存储/传送',IsVeer=1,move=0,AccessRange=2,Emoji=15,Action=9,NoShowIcon=1,DefaultDialog_class1=786066,ShadowCastOff=1,DefaultRolePartID=1102,}",
  [827338] = "{id=827338,NameZh='B格猫星人',ShowName=2,MapIcon='map_exchange',AtlasOpt='guild',Position='交易所职员',Body=1102,Gender=1,Hair=1102,Face=400144,Desc='大陆上最神秘的经贸平台组织，旗下业务范围几乎覆盖整个米德加尔特，甚至连遥远的海外也有其分公司，据爱尔贝塔商业报透露。这帮神秘的黑衣墨镜家伙几乎已经控制了整个大陆的交易和经济…',MoveSpdRate=1,DefaultDialog=785340,NpcFunction={{type=5000}},FnIcon='icon_60',FnDesc='交易所',IsVeer=1,move=0,AccessRange=2,Emoji=14,Action=9,NoShowIcon=1,LoadShowSize=0.9,Purikura='BigCat_Star',PurikuraBG='Adventure_bg_NPC2',DefaultDialog_class1=785341,ShadowCastOff=1,DefaultRolePartID=1052,}",
